left to right direction

package &quot;Слой 1 — Память
(Статья 0108)&quot; as C1 #E8F5E9 {
  rectangle &quot;**EAGER**
Панель инструментов
Автоматически загружено&quot; as EAG
  rectangle &quot;**LAZY**
Руководство владельца
Загружается по требованию&quot; as LAZ
  EAG -[hidden]right-&amp;gt; LAZ
}

package &quot;Слой 2 — Старение
(Статья 0110)&quot; as C2 #FFF9C4 {
  rectangle &quot;**HOT**
10 активных сессий
~300 строк&quot; as HOT
  rectangle &quot;**WARM**
Ссылки
Процедуры&quot; as WRM
  rectangle &quot;**COLD**
backup/
Холодная волна&quot; as CLD
  HOT -[hidden]right-&amp;gt; WRM
  WRM -[hidden]right-&amp;gt; CLD
}

package &quot;Слой 3 — Триггер
(Сегодня)&quot; as C3 #BBDEFB {
  rectangle &quot;**Авто**
N % 10 == 0&quot; as AUTO
  rectangle &quot;Порог
&amp;gt; 500 строк&quot; as SEUIL
  rectangle &quot;**Manuel**
резервное копирование с ротацией&quot; as MAN
  AUTO -[hidden]right-&amp;gt; SEUIL
  SEUIL -[hidden]right-&amp;gt; MAN
}

C1 --&amp;gt; C2 : &quot;Память растёт
→ нужен механизм
старения&quot;
C2 --&amp;gt; C3 : &quot;Старение
→ нужен триггер
для его выполнения&quot;

note bottom of C3
  ✅ Déployé sur 6 projets
  magic-stick · bakery-gradle
  plantuml-gradle · cheroliv.com
