&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;outputs.dir(cucumberReportsDir)&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
