&lt;li&gt;&lt;a href=&quot;#_диаграмма_развертывания&quot;&gt;Диаграмма развертывания&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_введение&quot;&gt;Введение&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Интернационализация (i18n) статического сайта может показаться сложной на первый взгляд, но JBake в сочетании с Thymeleaf предоставляет элегантные решения для создания многоязычного сайта. В этой статье я покажу, как я внедрил i18n в свой блог, охватывая как шаблоны, так и управление статьями на нескольких языках.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_диаграмма_вариантов_использования_use_case&quot;&gt;Диаграмма вариантов использования (Use Case)&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
left to right direction
skinparam packageStyle rectangle

actor &quot;Автор&quot; as author
actor &quot;Читатель FR&quot; as reader_fr
actor &quot;Читатель EN&quot; as reader_en

rectangle &quot;Многоязычный сайт JBake&quot; {
  usecase &quot;Написать статью FR&quot; as UC1
  usecase &quot;Написать статью EN&quot; as UC2
  usecase &quot;Настроить сообщения i18n&quot; as UC3
  usecase &quot;Сгенерировать сайт&quot; as UC4
  usecase &quot;Читать статью FR&quot; as UC5
  usecase &quot;Читать статью EN&quot; as UC6
  usecase &quot;Сменить язык&quot; as UC7
  usecase &quot;Смотреть доступные переводы&quot; as UC8
}

author --&amp;gt; UC1
author --&amp;gt; UC2
author --&amp;gt; UC3
author --&amp;gt; UC4

reader_fr --&amp;gt; UC5
reader_fr --&amp;gt; UC7
reader_fr --&amp;gt; UC8

reader_en --&amp;gt; UC6
reader_en --&amp;gt; UC7
reader_en --&amp;gt; UC8

UC1 ..&amp;gt; UC4 : &amp;lt;&amp;lt;include&amp;gt;&amp;gt;
UC2 ..&amp;gt; UC4 : &amp;lt;&amp;lt;include&amp;gt;&amp;gt;
UC3 ..&amp;gt; UC4 : &amp;lt;&amp;lt;include&amp;gt;&amp;gt;
UC5 ..&amp;gt; UC8 : &amp;lt;&amp;lt;extend&amp;gt;&amp;gt;
UC6 ..&amp;gt; UC8 : &amp;lt;&amp;lt;extend&amp;gt;&amp;gt;
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_архитектура_интернационализации&quot;&gt;Архитектура интернационализации&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Наш подход опирается на два столпа:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;i18n шаблонизации&lt;/strong&gt;: использование файлов сообщений Thymeleaf для элементов интерфейса&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Локализация содержимого&lt;/strong&gt;организация статей по языку в специализированной структуре каталогов&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_схема_структуры_организация_файлов&quot;&gt;Схема структуры (организация файлов)&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
@startsalt
{
{T
+ projet-jbake
++ content
+++ blog
++++ 2024
+++++ fr
++++++ article1.adoc
++++++ article2.adoc
+++++ en
++++++ article1.adoc
++++++ article2.adoc
++++ 2025
+++++ fr
++++++ guide-i18n.adoc
+++++ en
++++++ i18n-guide.adoc
++ templates
+++ post.html
+++ index.html
+++ index_en.html
+++ messages.properties
+++ messages_fr.properties
+++ messages_en.properties
++ assets
+++ css
+++ js
+++ img
++ jbake.properties
++ output
+++ fr
++++ blog
+++++ 2025
++++++ guide-i18n.html
+++ en
++++ blog
+++++ 2025
++++++ i18n-guide.html
}
}
@endsalt
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_почему_такой_подход&quot;&gt;Почему такой подход?&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Это разделение позволяет:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Поддерживать согласованность в интерфейсе независимо от языка&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Управлять содержимым и переводами статей независимо&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Облегчить добавление новых языков без значительного рефакторинга&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Разрешить статьи, доступные только на некоторых языках&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_диаграмма_компонентов&quot;&gt;Диаграмма компонентов&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam componentStyle rectangle

package &quot;Источники&quot; {
  folder &quot;content/blog/2025/&quot; {
    folder &quot;fr/&quot; as content_fr {
      [article1.adoc]
      [article2.adoc]
    }
    folder &quot;en/&quot; as content_en {
      [article1.adoc] as article1_en
      [article2.adoc] as article2_en
    }
  }

  folder &quot;шаблоны/&quot; {
    [post.html]
    [index.html]
    [index_en.html]
  }

  folder &quot;сообщения/&quot; {
    [messages_fr.properties]
    [messages_en.properties]
  }

  [jbake.properties]
}

package &quot;JBake Движок&quot; {
  [Parser AsciiDoc] as parser
  [Template Engine\nThymeleaf] as thymeleaf
  [Generator] as generator
  [I18n Resolver] as i18n
}

package &quot;Сгенерированный сайт&quot; {
  folder &quot;fr/&quot; {
    folder &quot;блог/2025/&quot; as blog_fr {
      [article1.html]
      [article2.html]
    }
  }

  folder &quot;en/&quot; {
    folder &quot;блог/2025/&quot; as blog_en {
      [article1.html] as article1_html_en
      [article2.html] as article2_html_en
    }
  }
}

content_fr --&amp;gt; parser
content_en --&amp;gt; parser
parser --&amp;gt; generator

templates --&amp;gt; thymeleaf
messages --&amp;gt; i18n
i18n --&amp;gt; thymeleaf
thymeleaf --&amp;gt; generator
jbake.properties --&amp;gt; generator

generator --&amp;gt; blog_fr
generator --&amp;gt; blog_en
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_i18n_шаблонизации_с_thymeleaf&quot;&gt;I18n шаблонизации с Thymeleaf&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_структура_файлов_сообщений&quot;&gt;Структура файлов сообщений&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Первый шаг заключается в создании файлов свойств для каждого поддерживаемого языка :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-text hljs&quot; data-lang=&quot;text&quot;&gt;src/jbake/templates/
├── messages.properties        # Fallback par défaut
├── messages_fr.properties     # Français
├── messages_en.properties     # Anglais
└── messages_de.properties     # Allemand&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_содержание_файлов_сообщений&quot;&gt;Содержание файлов сообщений&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Вот пример файла`messages_fr.properties`:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-properties hljs&quot; data-lang=&quot;properties&quot;&gt;# Navigation
nav.home=Accueil
nav.blog=Blog
nav.about=À propos
nav.contact=Contact

# Articles
article.readmore=Lire la suite
article.published=Publié le
article.tags=Étiquettes
article.also.available=Également disponible en

# Interface
site.title=Mon Blog Technique
site.description=Partage de connaissances et expériences
footer.copyright=© 2025 Tous droits réservés
search.placeholder=Rechercher un article...&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;И его английский эквивалент`messages_en.properties`:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-properties hljs&quot; data-lang=&quot;properties&quot;&gt;# Navigation
nav.home=Home
nav.blog=Blog
nav.about=About
nav.contact=Contact

# Articles
article.readmore=Read more
article.published=Published on
article.tags=Tags
article.also.available=Also available in

# Interface
site.title=My Tech Blog
site.description=Sharing knowledge and experiences
footer.copyright=© 2025 All rights reserved
search.placeholder=Search articles...&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_использование_в_шаблонах&quot;&gt;Использование в шаблонах&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;В ваших шаблонах Thymeleaf используйте синтаксис`#{}`для доступа к сообщениям :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-html hljs&quot; data-lang=&quot;html&quot;&gt;&amp;lt;!DOCTYPE html&amp;gt;
&amp;lt;html xmlns:th=&quot;http://www.thymeleaf.org&quot;&amp;gt;
&amp;lt;head&amp;gt;
    &amp;lt;title th:text=&quot;#{site.title}&quot;&amp;gt;Mon Blog&amp;lt;/title&amp;gt;
    &amp;lt;meta name=&quot;description&quot; th:content=&quot;#{site.description}&quot; /&amp;gt;
&amp;lt;/head&amp;gt;
&amp;lt;body&amp;gt;
    &amp;lt;nav&amp;gt;
        &amp;lt;a th:href=&quot;@{/}&quot; th:text=&quot;#{nav.home}&quot;&amp;gt;Accueil&amp;lt;/a&amp;gt;
        &amp;lt;a th:href=&quot;@{/blog/}&quot; th:text=&quot;#{nav.blog}&quot;&amp;gt;Blog&amp;lt;/a&amp;gt;
        &amp;lt;a th:href=&quot;@{/about.html}&quot; th:text=&quot;#{nav.about}&quot;&amp;gt;À propos&amp;lt;/a&amp;gt;
    &amp;lt;/nav&amp;gt;

    &amp;lt;footer&amp;gt;
        &amp;lt;p th:text=&quot;#{footer.copyright}&quot;&amp;gt;Copyright&amp;lt;/p&amp;gt;
    &amp;lt;/footer&amp;gt;
&amp;lt;/body&amp;gt;
&amp;lt;/html&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_диаграмма_последовательности_разрешение_i18n&quot;&gt;Диаграмма последовательности - Разрешение i18n&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
actor Auteur
participant JBake
participant &quot;AsciiDoc\nанализатор&quot; as parser
participant &quot;Thymeleaf
Двигатель&quot; as thymeleaf
participant &quot;I18n
резолвер&quot; as i18n
database &quot;messages_*.properties&quot; as messages

Auteur -&amp;gt; JBake: jbake -b
activate JBake

JBake -&amp;gt; parser: Lire article.fr.adoc
activate parser
parser --&amp;gt; JBake: Contenu + métadonnées\n(lang=fr, article-id=xyz)
deactivate parser

JBake -&amp;gt; parser: Lire article.en.adoc
activate parser
parser --&amp;gt; JBake: Contenu + métadonnées\n(lang=en, article-id=xyz)
deactivate parser

JBake -&amp;gt; thymeleaf: Générer page FR
activate thymeleaf

thymeleaf -&amp;gt; i18n: Résoudre #{nav.home}
activate i18n
i18n -&amp;gt; messages: Lire messages_fr.properties
messages --&amp;gt; i18n: &quot;Главная&quot;
i18n --&amp;gt; thymeleaf: &quot;Главная&quot;
deactivate i18n

thymeleaf -&amp;gt; JBake: Rechercher traductions\n(article-id=xyz, lang!=fr)
JBake --&amp;gt; thymeleaf: article.en.html trouvé

thymeleaf --&amp;gt; JBake: /fr/blog/article.html
deactivate thymeleaf

JBake -&amp;gt; thymeleaf: Générer page EN
activate thymeleaf

thymeleaf -&amp;gt; i18n: Résoudre #{nav.home}
activate i18n
i18n -&amp;gt; messages: Lire messages_en.properties
messages --&amp;gt; i18n: &quot;Дом&quot;
i18n --&amp;gt; thymeleaf: &quot;Дом&quot;
deactivate i18n

thymeleaf -&amp;gt; JBake: Rechercher traductions\n(article-id=xyz, lang!=en)
JBake --&amp;gt; thymeleaf: article.fr.html trouvé

thymeleaf --&amp;gt; JBake: /en/blog/article.html
deactivate thymeleaf

JBake --&amp;gt; Auteur: Site généré
deactivate JBake
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_настройка_локали_в_jbake&quot;&gt;Настройка локали в JBake&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;В вашем файле`jbake.properties`, установите локаль по умолчанию :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-properties hljs&quot; data-lang=&quot;properties&quot;&gt;# Locale par défaut
thymeleaf.locale=fr

# Encodage
template.encoding=UTF-8&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_i18n_статей_организация_по_папкам&quot;&gt;I18n статей: организация по папкам&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_схема_потока_flow_генерация&quot;&gt;Схема потока (Flow) - Генерация&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
start

:Lire jbake.properties;
:Charger configuration i18n;

partition &quot;Для каждого файла AsciiDoc&quot; {
  :Lire métadonnées\n(:jbake-lang:, :jbake-article-id:);
  :Parser contenu AsciiDoc;
  :Stocker en mémoire avec langue;
}

partition &quot;Для каждого шаблона&quot; {
  :Charger template Thymeleaf;
  :Identifier langue cible;
  :Charger messages_{lang}.properties;

  partition &quot;Фильтрация содержимого&quot; {
    :Filtrer articles par langue;
    :Grouper traductions\npar article-id;
  }

  :Appliquer template avec i18n;
  :Générer HTML dans /{lang}/;
}

:Copier assets statiques;
:Générer sitemap multilingue;
:Générer flux RSS par langue;

stop
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_структура_папок&quot;&gt;Структура папок&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Вместо использования суффиксов в именах файлов я выбрал организацию по папкам, которая обеспечивает большую ясность и поддерживаемость :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-text hljs&quot; data-lang=&quot;text&quot;&gt;content/blog/
├── 2024/
│   ├── fr/
│   │   ├── introduction-jbake.adoc
│   │   ├── guide-thymeleaf.adoc
│   │   └── astuces-asciidoc.adoc
│   └── en/
│       ├── introduction-jbake.adoc
│       ├── thymeleaf-guide.adoc
│       └── asciidoc-tips.adoc
└── 2025/
    ├── fr/
    │   └── internationalisation-jbake.adoc
    └── en/
        └── jbake-internationalization.adoc&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_преимущества_этого_подхода&quot;&gt;Преимущества этого подхода&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Эта структура имеет несколько преимуществ:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Чёткое разделение&lt;/strong&gt;: каждый язык имеет своё собственное пространство&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Гибкое именование&lt;/strong&gt;: файлы могут иметь разные имена в зависимости от языка&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Масштабируемость&lt;/strong&gt;: легко добавить новый язык&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Естественная организация&lt;/strong&gt;: следует временной логике JBake&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_метаданные_статей&quot;&gt;Метаданные статей&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Каждая статья должна содержать метаданные для обеспечения связи между переводами. Вот пример :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Французская версия&lt;/strong&gt;(&lt;code&gt;2025/fr/internationalisation-jbake.adoc&lt;/code&gt;) :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;= Internationalisation d&#39;un site statique JBake
:jbake-type: post
:jbake-status: published
:jbake-date: 2025-10-20
:jbake-lang: fr
:jbake-article-id: jbake-i18n-thymeleaf
:jbake-tags: jbake, thymeleaf, i18n
:jbake-description: Guide pour mettre en place l&#39;i18n avec JBake&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Английская версия&lt;/strong&gt;(&lt;code&gt;2025/en/jbake-internationalization.adoc&lt;/code&gt;) :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;= Internationalizing a JBake Static Site
:jbake-type: post
:jbake-status: published
:jbake-date: 2025-10-20
:jbake-lang: en
:jbake-article-id: jbake-i18n-thymeleaf
:jbake-tags: jbake, thymeleaf, i18n
:jbake-description: Guide to implement i18n with JBake&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ПРИМЕЧАНИЕ: Атрибут`:jbake-article-id:`Это важно: он позволяет связывать различные переводы одной и той же статьи.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_конфигурация_url&quot;&gt;Конфигурация URL&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;В`jbake.properties`, настройте шаблон URL для включения языка :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-properties hljs&quot; data-lang=&quot;properties&quot;&gt;# Pattern d&#39;URL avec langue
post.permalink.pattern=:lang/blog/:year/:name.html

# Langue par défaut
site.default.lang=fr&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Это будет генерировать URL-адреса вида :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;/fr/blog/2025/internationalisation-jbake.html&lt;/code&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;/en/blog/2025/jbake-internationalization.html&lt;/code&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_шаблоны_для_многоязычного_отображения&quot;&gt;Шаблоны для многоязычного отображения&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_шаблон_статьи_с_селектором_языка&quot;&gt;Шаблон статьи с селектором языка&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Создайте шаблон`post.html`который отображает доступные переводы :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-html hljs&quot; data-lang=&quot;html&quot;&gt;&amp;lt;!DOCTYPE html&amp;gt;
&amp;lt;html xmlns:th=&quot;http://www.thymeleaf.org&quot;&amp;gt;
&amp;lt;head&amp;gt;
    &amp;lt;title th:text=&quot;${content.title}&quot;&amp;gt;Article&amp;lt;/title&amp;gt;
&amp;lt;/head&amp;gt;
&amp;lt;body&amp;gt;
    &amp;lt;article&amp;gt;
        &amp;lt;header&amp;gt;
            &amp;lt;h1 th:text=&quot;${content.title}&quot;&amp;gt;Titre&amp;lt;/h1&amp;gt;

            &amp;lt;div class=&quot;article-meta&quot;&amp;gt;
                &amp;lt;time th:text=&quot;${#dates.format(content.date, &#39;dd MMMM yyyy&#39;)}&quot;
                      th:attr=&quot;datetime=${#dates.format(content.date, &#39;yyyy-MM-dd&#39;)}&quot;&amp;gt;
                    Date
                &amp;lt;/time&amp;gt;

                &amp;lt;!-- Sélecteur de traductions --&amp;gt;
                &amp;lt;div class=&quot;translations&quot; th:if=&quot;${content[&#39;article-id&#39;]}&quot;&amp;gt;
                    &amp;lt;span th:text=&quot;#{article.also.available}&quot;&amp;gt;Aussi disponible en :&amp;lt;/span&amp;gt;
                    &amp;lt;ul class=&quot;language-list&quot;&amp;gt;
                        &amp;lt;li th:each=&quot;post : ${published_posts}&quot;
                            th:if=&quot;${post[&#39;article-id&#39;] == content[&#39;article-id&#39;] and post.lang != content.lang}&quot;&amp;gt;
                            &amp;lt;a th:href=&quot;${post.uri}&quot;
                               th:text=&quot;${post.lang.toUpperCase()}&quot;&amp;gt;
                                LANG
                            &amp;lt;/a&amp;gt;
                        &amp;lt;/li&amp;gt;
                    &amp;lt;/ul&amp;gt;
                &amp;lt;/div&amp;gt;
            &amp;lt;/div&amp;gt;
        &amp;lt;/header&amp;gt;

        &amp;lt;div class=&quot;content&quot; th:utext=&quot;${content.body}&quot;&amp;gt;
            Contenu de l&#39;article
        &amp;lt;/div&amp;gt;

        &amp;lt;footer class=&quot;article-footer&quot;&amp;gt;
            &amp;lt;div class=&quot;tags&quot; th:if=&quot;${content.tags}&quot;&amp;gt;
                &amp;lt;span th:text=&quot;#{article.tags}&quot;&amp;gt;Étiquettes :&amp;lt;/span&amp;gt;
                &amp;lt;span th:each=&quot;tag : ${content.tags}&quot;&amp;gt;
                    &amp;lt;a th:href=&quot;@{/tags/{tag}.html(tag=${tag})}&quot;
                       th:text=&quot;${tag}&quot;&amp;gt;tag&amp;lt;/a&amp;gt;
                &amp;lt;/span&amp;gt;
            &amp;lt;/div&amp;gt;
        &amp;lt;/footer&amp;gt;
    &amp;lt;/article&amp;gt;
&amp;lt;/body&amp;gt;
&amp;lt;/html&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_индекс_отфильтрованный_по_языку&quot;&gt;Индекс, отфильтрованный по языку&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Создайте шаблоны индекса для каждого языка:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;index.html&lt;/strong&gt;(французский индекс) :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-html hljs&quot; data-lang=&quot;html&quot;&gt;&amp;lt;!DOCTYPE html&amp;gt;
&amp;lt;html xmlns:th=&quot;http://www.thymeleaf.org&quot;&amp;gt;
&amp;lt;head&amp;gt;
    &amp;lt;title th:text=&quot;#{site.title}&quot;&amp;gt;Mon Blog&amp;lt;/title&amp;gt;
&amp;lt;/head&amp;gt;
&amp;lt;body&amp;gt;
    &amp;lt;main&amp;gt;
        &amp;lt;h1 th:text=&quot;#{nav.blog}&quot;&amp;gt;Blog&amp;lt;/h1&amp;gt;

        &amp;lt;div class=&quot;articles-list&quot;&amp;gt;
            &amp;lt;article th:each=&quot;post : ${published_posts}&quot;
                     th:if=&quot;${post.lang == &#39;fr&#39;}&quot;&amp;gt;
                &amp;lt;h2&amp;gt;
                    &amp;lt;a th:href=&quot;${post.uri}&quot; th:text=&quot;${post.title}&quot;&amp;gt;Titre&amp;lt;/a&amp;gt;
                &amp;lt;/h2&amp;gt;
                &amp;lt;time th:text=&quot;${#dates.format(post.date, &#39;dd MMMM yyyy&#39;)}&quot;&amp;gt;
                    Date
                &amp;lt;/time&amp;gt;
                &amp;lt;p th:text=&quot;${post.description}&quot;&amp;gt;Description&amp;lt;/p&amp;gt;
                &amp;lt;a th:href=&quot;${post.uri}&quot; th:text=&quot;#{article.readmore}&quot;&amp;gt;
                    Lire la suite
                &amp;lt;/a&amp;gt;
            &amp;lt;/article&amp;gt;
        &amp;lt;/div&amp;gt;
    &amp;lt;/main&amp;gt;
&amp;lt;/body&amp;gt;
&amp;lt;/html&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;index_en.html&lt;/strong&gt;(английский индекс) :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-html hljs&quot; data-lang=&quot;html&quot;&gt;&amp;lt;!DOCTYPE html&amp;gt;
&amp;lt;html xmlns:th=&quot;http://www.thymeleaf.org&quot;&amp;gt;
&amp;lt;head&amp;gt;
    &amp;lt;title th:text=&quot;#{site.title}&quot;&amp;gt;My Blog&amp;lt;/title&amp;gt;
&amp;lt;/head&amp;gt;
&amp;lt;body&amp;gt;
    &amp;lt;main&amp;gt;
        &amp;lt;h1 th:text=&quot;#{nav.blog}&quot;&amp;gt;Blog&amp;lt;/h1&amp;gt;

        &amp;lt;div class=&quot;articles-list&quot;&amp;gt;
            &amp;lt;article th:each=&quot;post : ${published_posts}&quot;
                     th:if=&quot;${post.lang == &#39;en&#39;}&quot;&amp;gt;
                &amp;lt;h2&amp;gt;
                    &amp;lt;a th:href=&quot;${post.uri}&quot; th:text=&quot;${post.title}&quot;&amp;gt;Title&amp;lt;/a&amp;gt;
                &amp;lt;/h2&amp;gt;
                &amp;lt;time th:text=&quot;${#dates.format(post.date, &#39;dd MMMM yyyy&#39;)}&quot;&amp;gt;
                    Date
                &amp;lt;/time&amp;gt;
                &amp;lt;p th:text=&quot;${post.description}&quot;&amp;gt;Description&amp;lt;/p&amp;gt;
                &amp;lt;a th:href=&quot;${post.uri}&quot; th:text=&quot;#{article.readmore}&quot;&amp;gt;
                    Read more
                &amp;lt;/a&amp;gt;
            &amp;lt;/article&amp;gt;
        &amp;lt;/div&amp;gt;
    &amp;lt;/main&amp;gt;
&amp;lt;/body&amp;gt;
&amp;lt;/html&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_навигация_между_языками&quot;&gt;Навигация между языками&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_глобальный_селектор_языка&quot;&gt;Глобальный селектор языка&lt;/h3&gt;

&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_блок_схема_пользовательское_чтение&quot;&gt;Блок-схема - Пользовательское чтение&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
start

:Utilisateur accède au site;

if (Langue préférée ?) then (FR)
  :Afficher /index.html;
  :Lister articles FR;
else (EN)
  :Afficher /en/index.html;
  :Lister articles EN;
endif

:Utilisateur clique sur article;

:Afficher article\navec métadonnées;

if (Traductions disponibles ?) then (oui)
  :Afficher sélecteur\nde traductions;

  if (Changement de langue ?) then (oui)
    :Rediriger vers\ntraduction;
    :Afficher article\ndans nouvelle langue;
  else (non)
    :Continuer lecture;
  endif
else (non)
  :Continuer lecture;
endif

stop
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Добавьте селектор языка в ваш основной шаблон:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-html hljs&quot; data-lang=&quot;html&quot;&gt;&amp;lt;nav class=&quot;language-switcher&quot;&amp;gt;
    &amp;lt;a href=&quot;/index.html&quot;
       th:classappend=&quot;${content.lang == &#39;fr&#39;} ? &#39;active&#39;&quot;
       title=&quot;Français&quot;&amp;gt;
        🇫🇷 FR
    &amp;lt;/a&amp;gt;
    &amp;lt;a href=&quot;/en/index.html&quot;
       th:classappend=&quot;${content.lang == &#39;en&#39;} ? &#39;active&#39;&quot;
       title=&quot;English&quot;&amp;gt;
        🇬🇧 EN
    &amp;lt;/a&amp;gt;
&amp;lt;/nav&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_стиль_css_для_селектора&quot;&gt;Стиль CSS для селектора&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-css hljs&quot; data-lang=&quot;css&quot;&gt;.language-switcher {
    display: flex;
    gap: 1rem;
    padding: 0.5rem;
    background: #f5f5f5;
    border-radius: 4px;
}

.language-switcher a {
    padding: 0.5rem 1rem;
    text-decoration: none;
    color: #333;
    border-radius: 4px;
    transition: background 0.2s;
}

.language-switcher a:hover {
    background: #e0e0e0;
}

.language-switcher a.active {
    background: #007bff;
    color: white;
}

.translations {
    margin: 1rem 0;
    padding: 1rem;
    background: #f8f9fa;
    border-left: 4px solid #007bff;
}

.language-list {
    display: inline-flex;
    gap: 0.5rem;
    list-style: none;
    padding: 0;
    margin: 0;
}

.language-list li::after {
    content: &quot;•&quot;;
    margin-left: 0.5rem;
}

.language-list li:last-child::after {
    content: &quot;&quot;;
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_rss_поток_по_языку&quot;&gt;RSS-поток по языку&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Для получения отдельных RSS‑потоков по языкам создайте отдельные шаблоны :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;feed.xml&lt;/strong&gt;(французский поток) :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-xml hljs&quot; data-lang=&quot;xml&quot;&gt;&amp;lt;?xml version=&quot;1.0&quot; encoding=&quot;UTF-8&quot;?&amp;gt;
&amp;lt;rss version=&quot;2.0&quot; xmlns:th=&quot;http://www.thymeleaf.org&quot;&amp;gt;
    &amp;lt;channel&amp;gt;
        &amp;lt;title th:text=&quot;#{site.title}&quot;&amp;gt;Mon Blog&amp;lt;/title&amp;gt;
        &amp;lt;link th:text=&quot;${config.site_host}&quot;&amp;gt;http://example.com&amp;lt;/link&amp;gt;
        &amp;lt;description th:text=&quot;#{site.description}&quot;&amp;gt;Description&amp;lt;/description&amp;gt;
        &amp;lt;language&amp;gt;fr&amp;lt;/language&amp;gt;

        &amp;lt;item th:each=&quot;post : ${published_posts}&quot;
              th:if=&quot;${post.lang == &#39;fr&#39;}&quot;&amp;gt;
            &amp;lt;title th:text=&quot;${post.title}&quot;&amp;gt;Titre&amp;lt;/title&amp;gt;
            &amp;lt;link th:text=&quot;${config.site_host + post.uri}&quot;&amp;gt;Lien&amp;lt;/link&amp;gt;
            &amp;lt;pubDate th:text=&quot;${#dates.format(post.date, &#39;EEE, dd MMM yyyy HH:mm:ss Z&#39;)}&quot;&amp;gt;
                Date
            &amp;lt;/pubDate&amp;gt;
            &amp;lt;description th:text=&quot;${post.description}&quot;&amp;gt;Description&amp;lt;/description&amp;gt;
        &amp;lt;/item&amp;gt;
    &amp;lt;/channel&amp;gt;
&amp;lt;/rss&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_лучшие_практики_и_советы&quot;&gt;Лучшие практики и советы&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_1_согласованность_идентификаторов_статей&quot;&gt;1. Согласованность идентификаторов статей&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Убедитесь, что`:jbake-article-id:`одинаков для всех переводов одной статьи. Используйте согласованный формат :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Предпочитайте идентификаторы на английском языке для универсальности&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Используйте дефисы для разделения слов&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Избегайте специальных символов&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_согласованные_даты&quot;&gt;Согласованные даты&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Все переводы статьи должны иметь одинаковую дату публикации (&lt;code&gt;:jbake-date:&lt;/code&gt;). Это облегчает сортировку и хронологический вывод.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_3_многоязычные_теги&quot;&gt;3. Многоязычные теги&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Для тегов у вас есть два варианта&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Вариант 1: Универсальные теги на английском&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;:jbake-tags: java, spring-boot, microservices&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Вариант 2 : Теги переведены с использованием маппинга&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;# Version française
:jbake-tags: java, spring-boot, microservices

# Version anglaise
:jbake-tags: java, spring-boot, microservices&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_4_управление_непереведёнными_статьями&quot;&gt;4. Управление непереведёнными статьями&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Не обязательно переводить все статьи. Если статья существует только на одном языке, она просто не появится в списках другого языка.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_5_многоязычная_карта_сайта&quot;&gt;5. Многоязычная карта сайта&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Создайте sitemap, включающий все языки :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-xml hljs&quot; data-lang=&quot;xml&quot;&gt;&amp;lt;?xml version=&quot;1.0&quot; encoding=&quot;UTF-8&quot;?&amp;gt;
&amp;lt;urlset xmlns=&quot;http://www.sitemaps.org/schemas/sitemap/0.9&quot;
        xmlns:xhtml=&quot;http://www.w3.org/1999/xhtml&quot;
        xmlns:th=&quot;http://www.thymeleaf.org&quot;&amp;gt;
    &amp;lt;url th:each=&quot;post : ${published_posts}&quot;&amp;gt;
        &amp;lt;loc th:text=&quot;${config.site_host + post.uri}&quot;&amp;gt;URL&amp;lt;/loc&amp;gt;
        &amp;lt;lastmod th:text=&quot;${#dates.format(post.date, &#39;yyyy-MM-dd&#39;)}&quot;&amp;gt;Date&amp;lt;/lastmod&amp;gt;

        &amp;lt;!-- Liens alternatifs pour les traductions --&amp;gt;
        &amp;lt;xhtml:link th:each=&quot;translation : ${published_posts}&quot;
                    th:if=&quot;${translation[&#39;article-id&#39;] == post[&#39;article-id&#39;] and translation.lang != post.lang}&quot;
                    rel=&quot;alternate&quot;
                    th:attr=&quot;hreflang=${translation.lang},href=${config.site_host + translation.uri}&quot; /&amp;gt;
    &amp;lt;/url&amp;gt;
&amp;lt;/urlset&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_вывод&quot;&gt;Вывод&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Международная версия сайта JBake с Thymeleaf — это надёжный и поддерживаемый подход. Разделив i18n шаблонов (через файлы сообщений) и i18n контента (через организацию в каталогах), вы получаете гибкую систему, которую можно легко развивать.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ключевые моменты, которые следует запомнить :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Файлы сообщений Thymeleaf&lt;/strong&gt;для пользовательского интерфейса&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Организация по папкам&lt;/strong&gt;(год/язык) для статей&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Идентификаторы статьи&lt;/strong&gt;для связывания переводов&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Выделенные шаблоны&lt;/strong&gt;для каждого языка&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;явные URL&lt;/strong&gt;включая код языка&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_диаграмма_развертывания&quot;&gt;Диаграмма развертывания&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
node &quot;Машина разработки&quot; {
  artifact &quot;источники&quot; {
    folder &quot;&amp;lt;/think&amp;gt;
&amp;lt;/think&amp;gt;
&amp;lt;/think&amp;gt;&quot;
    folder &quot;шаблоны/&quot;
    folder &quot;активы/&quot;
  }

  component &quot;JBake CLI&quot; as jbake

  Sources --&amp;gt; jbake : jbake -b
}

node &quot;Сервер сборки
(CI/CD)&quot; {
  component &quot;GitHub Actions
или GitLab CI&quot; as ci

  jbake --&amp;gt; ci : push
}

cloud &quot;CDN / хостинг&quot; {
  node &quot;Статический веб-сервер&quot; {
    artifact &quot;Сгенерированный сайт&quot; {
      folder &quot;/fr/blog/&quot;
      folder &quot;/en/blog/&quot;
      folder &quot;/assets/&quot;
    }
  }
}

ci --&amp;gt; &quot;Сгенерированный сайт&quot; : déploiement

actor &quot;Читатели&quot; as users

users --&amp;gt; &quot;Статический веб-сервер&quot; : HTTPS
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Эта архитектура позволяет вам начать просто с двумя языками и добавлять другие без значительного рефакторинга. Всё остаётся полностью статическим и производительным, соответствующим философии JBake.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Хорошего мультиязычного развития! 🌍&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Table of Contents&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_введение&quot;&gt;Введение&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_скачивание_tor_и_его_подписи&quot;&gt;Скачивание Tor и его подписи&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_криптографическая_проверка_подписи&quot;&gt;Криптографическая проверка подписи&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_1_импортировать_открытый_ключ_проекта_tor&quot;&gt;1. Импортировать открытый ключ проекта Tor&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_2_проверить_подпись&quot;&gt;2. Проверить подпись&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_практический_пример_подпись_действительна_но_ключ_не_сертифицирован&quot;&gt;Практический пример: Подпись действительна, но ключ не сертифицирован&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_зачем_проверять_подпись&quot;&gt;Зачем проверять подпись?&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_извлечение_и_запуск_tor_browser&quot;&gt;Извлечение и запуск Tor Browser&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_интеграция_в_рабочий_стол_ubuntu&quot;&gt;Интеграция в рабочий стол Ubuntu&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_исследовать_образовательные_ресурсы_с_помощью_tor&quot;&gt;Исследовать образовательные ресурсы с помощью Tor&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_обновление_tor_browser&quot;&gt;Обновление Tor Browser&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_вывод&quot;&gt;Вывод&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_ссылки&quot;&gt;Ссылки&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_введение&quot;&gt;Введение&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;В мире, где цифровая конфиденциальность всё больше подвергается угрозе, &lt;strong&gt;Tor Browser&lt;/strong&gt; остаётся важным инструментом для сохранения анонимности и свободы информации. Однако важно никогда не запускать загруженное программное обеспечение без наличия&lt;strong&gt;проверил его подлинность&lt;/strong&gt;. Эта статья представляет полный метод для:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;Скачать &lt;strong&gt;Tor Browser&lt;/strong&gt; и его подпись`.asc`&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Проверить валидность скачанного файла&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Установить и запустить &lt;strong&gt;Tor Browser&lt;/strong&gt; в Ubuntu&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Добавить его в меню рабочего стола для повседневного использования&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Исследуйте образовательные ресурсы и этичный OSINT через Tor&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_скачивание_tor_и_его_подписи&quot;&gt;Скачивание Tor и его подписи&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Создайте отдельную папку для браузера Tor:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;mkdir -p ~/workspace/tipiak/tor
cd ~/workspace/tipiak/tor&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Затем загрузите архив браузера Tor и его подпись:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;wget https://www.torproject.org/dist/torbrowser/14.5.7/tor-browser-linux-x86_64-14.5.7.tar.xz
wget https://www.torproject.org/dist/torbrowser/14.5.7/tor-browser-linux-x86_64-14.5.7.tar.xz.asc&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_криптографическая_проверка_подписи&quot;&gt;Криптографическая проверка подписи&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Этот этап есть&lt;strong&gt;незаменимый&lt;/strong&gt;чтобы убедиться, что загруженный файл действительно взят из &lt;strong&gt;Tor Project&lt;/strong&gt; и не был изменён.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_1_импортировать_открытый_ключ_проекта_tor&quot;&gt;1. Импортировать открытый ключ проекта Tor&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;gpg --auto-key-locate nodefault,wkd --locate-keys torbrowser@torproject.org&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Проверьте, что ключ импортирован правильно :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;gpg --list-keys torbrowser@torproject.org&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_2_проверить_подпись&quot;&gt;2. Проверить подпись&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;gpg --verify tor-browser-linux-x86_64-14.5.7.tar.xz.asc tor-browser-linux-x86_64-14.5.7.tar.xz&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Если все правильно, будет отображаться следующее сообщение :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-none hljs&quot;&gt;gpg: Good signature from &quot;Tor Browser Developers (signing key)&quot;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;При предупреждении о неподтверждённом ключе это просто означает, что вы ещё не подписали доверенный ключ проекта Tor, но подпись остаётся действительной.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_практический_пример_подпись_действительна_но_ключ_не_сертифицирован&quot;&gt;Практический пример: Подпись действительна, но ключ не сертифицирован&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Часто встречается сообщение такого вида при проверке :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-none hljs&quot;&gt;gpg --verify tor-browser-linux-x86_64-14.5.7.tar.xz.asc tor-browser-linux-x86_64-14.5.7.tar.xz
gpg: Signature faite le mar. 16 sept. 2025 14:26:26 CEST
gpg:                avec la clef RSA CAAE408AEBE2288E96FC5D5E157432CF78A65729
gpg: Bonne signature de « Tor Browser Developers (signing key) &amp;lt;torbrowser@torproject.org&amp;gt; » [inconnu]
gpg: Attention : cette clef n&#39;est pas certifiée avec une signature de confiance.
gpg:          Rien n&#39;indique que la signature appartient à son propriétaire.
Empreinte de clef principale : EF6E 286D DA85 EA2A 4BA7  DE68 4E2C 6E87 9329 8290
     Empreinte de la sous-clef : CAAE 408A EBE2 288E 96FC  5D5E 1574 32CF 78A6 5729&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Это сообщение указывает, что подпись технически «хорошая» (файл не был изменён), но ваша система GPG не может &lt;strong&gt;подтвердить доверие&lt;/strong&gt; к самому ключу. Для устранения этого сомнения необходимо сравнить отпечаток главного ключа (&lt;code&gt;EF6E 286D DA85 EA2A 4BA7 DE68 4E2C 6E87 9329 8290&lt;/code&gt;) с той, опубликованной на официальном сайте Tor Project.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Согласно официальному сайту, ожидаемый отпечаток:`EF6E286DDA85EA2A4BA7DE684E2C6E8793298290`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Поскольку отображаемый отпечаток от`gpg`соответствует &lt;strong&gt;точно&lt;/strong&gt; той, что на официальном сайте, вы можете быть уверены, что ключ легитимный и файл безопасен. Предупреждение о «несертифицированном ключе» тогда является информацией о вашей локальной конфигурации GPG, а не о действительности подписи или подлинности файла.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_зачем_проверять_подпись&quot;&gt;Зачем проверять подпись?&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Проверка подписей GPG — это фундаментальный акт цифровой безопасности. Она позволяет:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Гарантировать&lt;strong&gt;подлинность&lt;/strong&gt;загруженного программного обеспечения&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Предотвратить установку скомпрометированного файла злоумышленником&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;участвовать в&lt;strong&gt;цифровой суверенитет&lt;/strong&gt;индивидуальная&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Способствовать формированию ответственной и этичной цифровой культуры&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
left to right direction
actor &quot;Пользователь&quot; as U
actor &quot;Сервер TorProject&quot; as S

usecase &quot;Скачать Tor и его подпись&quot; as D
usecase &quot;Импортировать публичный ключ&quot; as K
usecase &quot;Проверить подпись GPG&quot; as V
usecase &quot;Установить и запустить Tor&quot; as I

U --&amp;gt; D
U --&amp;gt; K
U --&amp;gt; V
U --&amp;gt; I
S --&amp;gt; D

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_извлечение_и_запуск_tor_browser&quot;&gt;Извлечение и запуск Tor Browser&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Распакуйте загруженный архив :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;tar -xvf tor-browser-linux-x86_64-14.5.7.tar.xz
cd tor-browser&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Затем запустите браузер:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;./start-tor-browser.desktop&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;При первом запуске откроется окно настройки для установления соединения с сетью Tor.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_интеграция_в_рабочий_стол_ubuntu&quot;&gt;Интеграция в рабочий стол Ubuntu&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Чтобы добавить &lt;strong&gt;Tor Browser&lt;/strong&gt; в меню приложений:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;./start-tor-browser.desktop --register-app&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Вы можете затем:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Запустить &lt;strong&gt;Tor Browser&lt;/strong&gt; из меню приложений&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Добавить в избранное док&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Создать сочетание клавиш, если требуется&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
start
:Téléchargement de Tor;
:Importation de la clé GPG;
:Vérification de la signature;
if (Signature valide ?) then (Oui)
:Extraction du navigateur;
:Lancement du navigateur Tor;
:Enregistrement dans le bureau;
else (Non)
:Supprimer le fichier compromis;
endif
stop
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_исследовать_образовательные_ресурсы_с_помощью_tor&quot;&gt;Исследовать образовательные ресурсы с помощью Tor&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Tor — это не только инструмент анонимности. Он представляет собой портал доступа к образовательным и исследовательским ресурсам, в частности в следующих областях :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;OSINT (Открытые источники разведки)&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://inteltechniques.com&quot;&gt;https://inteltechniques.com&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://osintframework.com&quot;&gt;https://osintframework.com&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Образовательный обмен и open source&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://archive.org&quot;&gt;https://archive.org&lt;/a&gt;(доступ через Tor для большей конфиденциальности)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://github.com/&quot;&gt;https://github.com/&lt;/a&gt;(доступно через Tor)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://librarygenesis.pro&quot;&gt;https://librarygenesis.pro&lt;/a&gt;(доступ к свободной научной литературе)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Передача знаний и понимание человека в цифровом обществе&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Ресурсы о цифровой культуре, свободе выражения и доступе к знаниям&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Свободная документация о кибербезопасности и этике технологий&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_обновление_tor_browser&quot;&gt;Обновление Tor Browser&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Для обеспечения оптимальной безопасности крайне важно поддерживать &lt;strong&gt;Tor Browser&lt;/strong&gt; в актуальном состоянии. Браузер имеет встроенный механизм автоматического обновления, который может быть запущен из командной строки.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Из каталога установки Tor Browser достаточно перезапустить стартовый скрипт :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;cd ~/workspace/tipiak/tor/tor-browser
./start-tor-browser.desktop&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;При запуске &lt;strong&gt;Tor Browser&lt;/strong&gt; автоматически проверит наличие новой версии. Если она есть, он загрузит и установит её для вас.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Этот простой метод гарантирует, что у вас всегда будут последние исправления безопасности и новейшие улучшения, что необходимо для безопасного просмотра.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_вывод&quot;&gt;Вывод&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Проверка своих загрузок — это важный рефлекс для любого человека, желающего развиваться в безопасной цифровой среде. Устанавливать Tor проверенным способом — это&lt;strong&gt;защищать свою цифровую целостность&lt;/strong&gt;, &lt;strong&gt;сохранить доверие к свободному программному обеспечению&lt;/strong&gt;, et &lt;strong&gt;укрепить свою информационную автономию&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Цифровая безопасность является актом осознанности, а не паранойи.&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
title Синтетический обзор использования Tor
actor Utilisateur
rectangle &quot;Браузер Тор&quot; {
rectangle &quot;Анонимность&quot; as A
rectangle &quot;Поиск OSINT&quot; as O
rectangle &quot;Образовательный обмен&quot; as E
}
Utilisateur --&amp;gt; A
Utilisateur --&amp;gt; O
Utilisateur --&amp;gt; E
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_ссылки&quot;&gt;Ссылки&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Официальный сайт Tor Project :https://www.torproject.org/download/[&lt;a href=&quot;https://www.torproject.org/download/&quot; class=&quot;bare&quot;&gt;https://www.torproject.org/download/&lt;/a&gt;]&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Документация проверки подписей:https://support.torproject.org/tbb/how-to-verify-signature/[&lt;a href=&quot;https://support.torproject.org/tbb/how-to-verify-signature/&quot; class=&quot;bare&quot;&gt;https://support.torproject.org/tbb/how-to-verify-signature/&lt;/a&gt;]&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Документация Ubuntu :https://ubuntu.com[&lt;a href=&quot;https://ubuntu.com&quot; class=&quot;bare&quot;&gt;https://ubuntu.com&lt;/a&gt;]&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Образовательный архив:https://archive.org/details/opensource[&lt;a href=&quot;https://archive.org/details/opensource&quot; class=&quot;bare&quot;&gt;https://archive.org/details/opensource&lt;/a&gt;]&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;admonitionblock note&quot;&gt;
&lt;table&gt;
&lt;tr&gt;
&lt;td class=&quot;icon&quot;&gt;
&lt;i class=&quot;fa icon-note&quot; title=&quot;Note&quot;&gt;&lt;/i&gt;
&lt;/td&gt;
&lt;td class=&quot;content&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Эта статья является частью серии &lt;strong&gt;Безопасность и цифровое сознание&lt;/strong&gt;, направленное на продвижение ответственных и педагогических практик вокруг свободных инструментов.&lt;/p&gt;
&lt;/div&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Sommaire&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_введение&quot;&gt;Введение&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_1_каталог_версий_libs_versions_toml_напоминание&quot;&gt;1. Каталог версий (&lt;code&gt;libs.versions.toml&lt;/code&gt;) : напоминание&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_2_проблема_композитная_сборка_и_два_разделенных_мира&quot;&gt;2. Проблема: композитная сборка и два разделенных мира&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_3_решение_совместное_использование_разрешения_зависимостей&quot;&gt;3. Решение: Совместное использование разрешения зависимостей&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_4_вывод_сила_хорошо_управляемых_композитных_сборок&quot;&gt;4. Вывод: Сила хорошо управляемых композитных сборок&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_введение&quot;&gt;Введение&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;Public cible : разработчики Gradle, сталкивающиеся с управлением зависимостями в многосборных проектах.&lt;/div&gt;
&lt;p&gt;В нашем стремлении создать плагин`site-baker`, мы стремились поддерживать чистую и централизованную кодовую базу. Одной из лучших практик в современной экосистеме Gradle является использование&lt;strong&gt;каталог версий&lt;/strong&gt;(&lt;code&gt;libs.versions.toml&lt;/code&gt;) для управления зависимостями. Но что происходит, когда ваш проект становится более сложным, как&lt;strong&gt;строить композит&lt;/strong&gt;где независимая сборка (наш плагин) должна быть включена в другую ?&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Именно там наше приключение приняло неожиданный оборот. Мы хотели, чтобы наш плагин`site-baker`, который сам по себе является проектом Gradle, использует тот же каталог версий, что и наш основной проект. Эта статья, пятая в нашей серии, рассказывает, как мы решили эту проблему.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_1_каталог_версий_libs_versions_toml_напоминание&quot;&gt;1. Каталог версий (&lt;code&gt;libs.versions.toml&lt;/code&gt;) : напоминание&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Файл`gradle/libs.versions.toml`— это функция Gradle, позволяющая централизовать версии и координаты зависимостей вашего проекта. Обычно она состоит из четырёх разделов:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;[versions]&lt;/code&gt;: Определяет псевдонимы для номеров версий (например:`kotlin = &quot;1.9.20&quot;`).&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;[libraries]&lt;/code&gt;: Определяет псевдонимы для полных зависимостей, используя версии, указанные выше (например:`kotlin-stdlib = { module = &quot;org.jetbrains.kotlin:kotlin-stdlib&quot;, version.ref = &quot;kotlin&quot; }`).&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;[bundles]`Объединяет несколько библиотек под одним псевдонимом (например:`jackson = [&quot;jackson-core&quot;, &quot;jackson-databind&quot;]&lt;/code&gt;).&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;[plugins]&lt;/code&gt;: Определяет псевдонимы для плагинов Gradle.&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;После того как оно определено, Gradle автоматически генерирует типизированные аксессоры, что делает ваш`build.gradle.kts`гораздо более читаемый :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;dependencies {
    // Au lieu de : implementation(&quot;org.jetbrains.kotlin:kotlin-stdlib:1.9.20&quot;)
    implementation(libs.kotlin.stdlib)
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;title&quot;&gt;Pоток данных каталога версий&lt;/div&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
!theme plain
file &quot;gradle/libs.versions.toml&quot; as Toml
node &quot;Грэдл&quot; as G
file &quot;build.gradle.kts&quot; as BuildScript

Toml --&amp;gt; G : &quot;читается&quot;
G --&amp;gt; BuildScript : &quot;генерирует аксессор `libs&quot;
BuildScript -&amp;gt; G : &quot;используй `libs` для объявления зависимостей&quot;
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_2_проблема_композитная_сборка_и_два_разделенных_мира&quot;&gt;2. Проблема: композитная сборка и два разделенных мира&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Наша структура проекта — это&lt;strong&gt;построить композит&lt;/strong&gt;. Главный проект (&lt;code&gt;thymeleaf.cheroliv.com&lt;/code&gt;) включает проект плагина (&lt;code&gt;site-baker&lt;/code&gt;) через команду`includeBuild(&quot;site-baker&quot;)&lt;code&gt;в файле`settings.gradle.kts&lt;/code&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;title&quot;&gt;Структура композитной сборки&lt;/div&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
!theme plain
package &quot;Главный проект&quot; {
  file &quot;settings.gradle.kts&quot; as MainSettings
  folder &quot;Грэдл&quot; {
    file &quot;libs.versions.toml&quot; as MainToml
  }
}

package &quot;Плагин `site-baker` (Встроено)&quot; {
  file &quot;settings.gradle.kts&quot; as PluginSettings
  file &quot;build.gradle.kts&quot; as PluginBuild
}

MainSettings -&amp;gt; PluginSettings : `includeBuild(&quot;site-baker&quot;)`
PluginBuild ..&amp;gt; MainToml : **Voulait accéder à...**
note right on link: ...mais ne pouvait pas !
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Проблема в том, что, по умолчанию, включённый build - это&lt;strong&gt;отдельный мир&lt;/strong&gt;. У него есть своя конфигурация, свой жизненный цикл, и он не видит файл`libs.versions.toml`главной сборки. Наш`plugin/build.gradle.kts`пытался использовать`libs.plugins.kotlin.jvm`, но объект`libs`Он не был сгенерирован из правильного файла TOML, что привело к ошибкам сборки.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_3_решение_совместное_использование_разрешения_зависимостей&quot;&gt;3. Решение: Совместное использование разрешения зависимостей&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;После нескольких поисков решение оказалось функцией Gradle, специально разработанной для этого случая :`dependencyResolutionManagement`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;В файле`settings.gradle.kts` du &lt;strong&gt;включённая сборка&lt;/strong&gt;(&lt;code&gt;site-baker/settings.gradle.kts&lt;/code&gt;), мы можем указать Gradle, где найти каталог версий для использования.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Это конфигурация, которую мы добавили к`site-baker/settings.gradle.kts`:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// site-baker/settings.gradle.kts

dependencyResolutionManagement {
    repositoriesMode.set(RepositoriesMode.FAIL_ON_PROJECT_REPOS)
    repositories {
        gradlePluginPortal()
        mavenCentral()
    }
    versionCatalogs {
        create(&quot;libs&quot;) {
            from(files(&quot;../gradle/libs.versions.toml&quot;))
        }
    }
}

rootProject.name = &quot;site-baker&quot;
include(&quot;plugin&quot;)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Давайте проанализируем важную часть:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;versionCatalogs {
    create(&quot;libs&quot;) { // Crée un catalogue nommé &#39;libs&#39;
        from(files(&quot;../gradle/libs.versions.toml&quot;)) // En utilisant ce fichier
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;create(&quot;libs&quot;)&lt;/code&gt;: Мы объявляем каталог версий, который будет доступен через псевдоним`libs`.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;from(files(&quot;../gradle/libs.versions.toml&quot;))`Это магия. Мы указываем Gradle, что источник этого каталога — файл TOML, расположенный в каталоге`gradle&lt;/code&gt; du &lt;strong&gt;родительский проект&lt;/strong&gt;(&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;)&lt;code&gt;../&lt;/code&gt;).&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;С этой конфигурацией сборка`site-baker`Теперь он знает, что ему нужно использовать каталог версий основного проекта. Объект`libs`сгенерировано правильно, и зависимости разрешены как ожидалось.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_4_вывод_сила_хорошо_управляемых_композитных_сборок&quot;&gt;4. Вывод: Сила хорошо управляемых композитных сборок&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Этот опыт был полон уроков. Каталог версий — фантастический инструмент для поддерживаемости, но его поведение в сценариях комбинированных сборок не всегда интуитивно понятно.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ключ в том, чтобы помнить, что включённая сборка остаётся независимой. Чтобы делиться конфигурациями, такими как каталог версий, необходимо использовать явные механизмы, предоставляемые Gradle, такие как блок`dependencyResolutionManagement`в`settings.gradle.kts`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Решив эту проблему, мы не только сделали нашу сборку более чистой, но и усилили целостность нашего проекта, убедившись, что плагин и основной проект используют единым источником правды для своих зависимостей.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;В следующей статье мы продолжим обогащать наш плагин, добавляя более сложные задачи, поскольку теперь наше управление зависимостями надёжно и централизовано.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Sommaire&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_введение&quot;&gt;Введение&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_симптом_призрачные_сборки&quot;&gt;Симптом: Призрачные сборки&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_расследование_что_такое_кэш_конфигурации&quot;&gt;Расследование: что такое кэш конфигурации?&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_причина_проблемы_несоответствующий_плагин&quot;&gt;Причина проблемы: Несоответствующий плагин&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_временное_решение_отключить_кэш&quot;&gt;Временное решение: отключить кэш&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_истинное_решение_сделать_плагин_совместимым&quot;&gt;Истинное решение : Сделать плагин совместимым&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_введение&quot;&gt;Введение&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;Целевая аудитория: Разработчики Gradle, уже сталкивавшиеся с &quot;волшебным&quot; или неожиданным поведением сборки.&lt;/div&gt;
&lt;p&gt;В нашем приключении по созданию плагина`site-baker`, мы следовали строгому подходу TDD. Каждая функция тестировалась, проверялась, и мы продвигались с уверенностью. И тогда, однажды, непредвиденное произошло. Сборки начали вести себя непредсказуемо. Изменения в логике плагина или в файлах конфигурации, казалось, игнорировались, и наши функциональные тесты, ранее надёжные, терпели неудачу без видимой причины.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Такая проблема может быть невероятно раздражающим. Он ставит под сомнение надежность инструмента и корректность нашего кода. После интенсивной сессии отладки виновный был идентифицирован: этот&lt;strong&gt;кеш конфигурации Gradle&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_симптом_призрачные_сборки&quot;&gt;Симптом: Призрачные сборки&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Проблема проявлялась несколькими способами :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;Я изменял строку символов в задаче`println`, но старая строка продолжала отображаться во время выполнения.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Я менял значение в моём файле`managed-jbake-context.yml`, но плагин вёл себя так, как будто файл не был изменён.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Функциональные тесты, которые создают тестовые проекты на лету, не проходили, потому что плагин, похоже, не обнаруживает только что созданные файлы конфигурации.&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Всё происходило так, будто Gradle выполнял &quot;призрачную&quot; версию нашей сборки, игнорируя наши самые последние изменения.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_расследование_что_такое_кэш_конфигурации&quot;&gt;Расследование: что такое кэш конфигурации?&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Кеш конфигурации — это относительно новая и чрезвычайно мощная функция Gradle, включённая по умолчанию в новых версиях. Её цель — ускорить сборки.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;div class=&quot;title&quot;&gt;Принцип прост :&lt;/div&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;При первом запуске, Gradle выполняет фазу&lt;strong&gt;Конфигурация&lt;/strong&gt;(чтение`build.gradle.kts`, создание задач, разрешение зависимостей) и строит граф задач.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;В конце этой фазы, Gradle&lt;strong&gt;сериализуй этот граф задач&lt;/strong&gt;и сохраняет его в кэше.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;При последующих запусках, если ничего не изменилось (скрипты сборки,&lt;code&gt;gradle.properties&lt;/code&gt;, и т.д.), Gradle&lt;strong&gt;полностью пропускает этап настройки&lt;/strong&gt;и повторно использует кэшированный граф задач&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Экономия времени поразительна в больших проектах. Однако эта производительность имеет свою цену: она накладывает строгие правила на то, как должны писаться плагины.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;title&quot;&gt;Жизненный цикл кэша конфигурации&lt;/div&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
start
:Première exécution;
:Phase de Configuration;
:Création du graphe de tâches;
:Mise en cache du graphe;
:Phase d&#39;Exécution;
end

start
:Exécution suivante;
if (Cache valide ?) then (oui)
  :Restauration du graphe depuis le cache;
  note right
    La phase de configuration
    est sautée !
  end note
else (non)
  :Phase de Configuration;
  :Mise à jour du cache;
endif
:Phase d&#39;Exécution;
stop
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_причина_проблемы_несоответствующий_плагин&quot;&gt;Причина проблемы: Несоответствующий плагин&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Наш плагин`site-baker`Нарушал, не зная об этом, несколько правил кэша конфигурации. Чтобы граф задач был сериализуемым, задачи не должны содержать ссылок на сложные объекты, подобные этому объекту.`Project`или читать файлы произвольно во время выполнения.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Наша основная ошибка заключалась в чтении содержимого YAML-файла прямо внутри логики выполнения задачи, используя ссылку на путь, хранящийся в нашем расширении. Этот подход несовместим с кэшированием, поскольку Gradle не может определить, изменилось ли содержимое файла, если это чтение не смоделировано как&lt;strong&gt;запись задачи&lt;/strong&gt;(empty)&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_временное_решение_отключить_кэш&quot;&gt;Временное решение: отключить кэш&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Чтобы разблокировать нас и восстановить предсказуемое поведение сборки, самое быстрое решение было отключить кэш конфигурации. Достаточно добавить следующую строку в файл`gradle.properties`du проекта, который использует плагин (или в нашем случае, тестовый проект)&lt;code&gt;site-baker&lt;/code&gt;).&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-properties hljs&quot; data-lang=&quot;properties&quot;&gt;# site-baker/gradle.properties
org.gradle.configuration-cache=false&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Мгновенно сборки вернули своё нормальное поведение. Каждый запуск перезапускал этап настройки, и наши изменения учитывались.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Однако это обходное решение, а не устойчивое решение. Оно жертвует производительностью и не устраняет основную проблему нашего плагина.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_истинное_решение_сделать_плагин_совместимым&quot;&gt;Истинное решение : Сделать плагин совместимым&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Чтобы плагин был хорошим гражданином современной экосистемы Gradle, он должен быть совместим с кешем конфигурации. Это подразумевает переосмысливание того, как данные поступают к нашим задачам.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ключ в том, чтобы использовать&lt;strong&gt;API поставщика&lt;/strong&gt;Gradle. Вместо передачи прямых значений (как`String` ou un &lt;code&gt;File&lt;/code&gt;) на наши задачи, мы должны потратить`Property&amp;lt;T&amp;gt;`или некоторых`Provider&amp;lt;T&amp;gt;`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;div class=&quot;title&quot;&gt;Вот план рефакторинга :&lt;/div&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Объявлять записи задач :&lt;/strong&gt;Задача, которая парсит файл YAML, должна объявить этот файл как вход. Для этого используется аннотация`@InputFile`.&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;[source,kotlin] (empty) @get:InputFile abstract val configFile: RegularFileProperty ----&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Sommaire&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_введение&quot;&gt;Введение&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_1_контекст_наш_плагин_site_baker&quot;&gt;1. Контекст: Наш плагин `site-baker&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_2_моделирование_конфигурации_в_kotlin&quot;&gt;2. Моделирование конфигурации в Kotlin&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_3_интеграция_jackson_в_build_gradle_kts&quot;&gt;3. Интеграция Jackson в `build.gradle.kts&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_4_подход_tdd_тестирование_парсинга_yaml&quot;&gt;4. Подход TDD : Тестирование парсинга YAML&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_4_1_тест_юнита_преобразовать_yaml_в_объект_kotlin&quot;&gt;4.1. Тест юнита: Преобразовать YAML в объект Kotlin&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_4_2_тест_функциональный_проверить_чтение_файла_конфигурации&quot;&gt;4.2. Тест функциональный: Проверить чтение файла конфигурации&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_5_визуализация_потока_парсинга&quot;&gt;5. Визуализация потока парсинга&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_заключение&quot;&gt;Заключение&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_введение&quot;&gt;Введение&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;Целевая аудитория: промежуточные разработчики Gradle, желающие управлять сложными конфигурациями.&lt;/div&gt;
&lt;p&gt;В разработке плагинов Gradle управление сложными конфигурациями является обычной задачей. Вместо того чтобы перегружать DSL сотнями свойств, часто чище и поддерживаемее определять конфигурацию во внешнем файле, например, в YAML. Эта статья проведет вас через интеграцию мощной библиотеки Jackson для парсинга файлов YAML в объекты Kotlin, применяя строгий подход TDD, чтобы обеспечить надежность нашего плагина.&lt;code&gt;site-baker&lt;/code&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_1_контекст_наш_плагин_site_baker&quot;&gt;1. Контекст: Наш плагин `site-baker&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Наш плагин`site-baker`предназначен для автоматизации генерации и развертывания статического сайта. Ему необходимо читать файл конфигурации YAML (&lt;code&gt;managed-jbake-context.yml&lt;/code&gt;) для получения информации, такой как пути исходных файлов, места развертывания и учетные данные Git.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;YAML конфигурация, которую мы хотим разобрать, выглядит так:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-yaml hljs&quot; data-lang=&quot;yaml&quot;&gt;bake:
  srcPath: &quot;./site/jbake&quot;
  destDirPath: &quot;bake&quot;
  cname: &quot;cheroliv.com&quot;
pushPage:
  from: &quot;bake&quot;
  to: &quot;cvs&quot;
  repo:
    name: &quot;trainings&quot;
    repository: &quot;https://github.com/pages-content/pages-content.github.io.git&quot;
    credentials:
      username: &quot;USERNAME&quot;
      password: &quot;SECRET_TOKEN&quot;
  branch: &quot;main&quot;
  message: &quot;cheroliv.com&quot;
# ... autres configurations (pushMaquette, supabase, etc.)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_2_моделирование_конфигурации_в_kotlin&quot;&gt;2. Моделирование конфигурации в Kotlin&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Перед парсингом нам нужно определить структуру наших данных на Kotlin. Jackson будет использовать эти классы для автоматического сопоставления содержимого YAML.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// plugin/src/main/kotlin/com/cheroliv/site/baker/data/SiteConfiguration.kt
package com.cheroliv.site.baker.data

import com.fasterxml.jackson.databind.ObjectMapper
import com.fasterxml.jackson.dataformat.yaml.YAMLFactory
import com.fasterxml.jackson.module.kotlin.readValue
import com.fasterxml.jackson.module.kotlin.registerKotlinModule

fun parseSiteConfiguration(yaml: String): SiteConfiguration {
    val mapper = ObjectMapper(YAMLFactory()).registerKotlinModule()
    return mapper.readValue(yaml)
}

data class GitPushConfiguration(
    val from: String = &quot;&quot;,
    val to: String = &quot;&quot;,
    val repo: RepositoryConfiguration = RepositoryConfiguration(),
    val branch: String = &quot;&quot;,
    val message: String = &quot;&quot;,
)

data class RepositoryConfiguration(
    val name: String = &quot;&quot;,
    val repository: String = &quot;&quot;,
    val credentials: RepositoryCredentials = RepositoryCredentials(),
) {
    companion object {
        const val ORIGIN = &quot;origin&quot;
        const val CNAME = &quot;CNAME&quot;
        const val REMOTE = &quot;remote&quot;
    }
}

data class RepositoryCredentials(val username: String = &quot;&quot;, val password: String = &quot;&quot;)

data class SiteConfiguration(
    val bake: BakeConfiguration = BakeConfiguration(),
    val pushPage: GitPushConfiguration = GitPushConfiguration(),
    val pushMaquette: GitPushConfiguration = GitPushConfiguration(),
    val pushSource: GitPushConfiguration? = null,
    val pushTemplate: GitPushConfiguration? = null,
    val supabase: SupabaseContactFormConfig? = null
)

data class BakeConfiguration(
    val srcPath: String = &quot;&quot;,
    val destDirPath: String = &quot;&quot;,
    val cname: String? = null,
)

// ... (autres data classes pour Supabase, si nécessaire)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Функция`parseSiteConfiguration`является нашей точкой входа для десериализации. Она использует`ObjectMapper`Джексона, настроенный с`YAMLFactory` pour le format YAML et `registerKotlinModule()`для поддержки особенностей Kotlin (например, значения свойств по умолчанию).&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_3_интеграция_jackson_в_build_gradle_kts&quot;&gt;3. Интеграция Jackson в `build.gradle.kts&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Чтобы использовать Jackson, мы должны добавить необходимые зависимости в`build.gradle.kts`нашего модуля`plugin` :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// plugin/build.gradle.kts
dependencies {
    // Jackson for YAML parsing
    implementation(&quot;com.fasterxml.jackson.module:jackson-module-kotlin:2.18.3&quot;)
    implementation(&quot;com.fasterxml.jackson.dataformat:jackson-dataformat-yaml:2.18.3&quot;)

    // ... autres dépendances
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Мы используем`jackson-module-kotlin`для поддержки Kotlin и`jackson-dataformat-yaml`pour управления форматом YAML.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_4_подход_tdd_тестирование_парсинга_yaml&quot;&gt;4. Подход TDD : Тестирование парсинга YAML&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Теперь применим TDD для проверки нашей логики парсинга.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_4_1_тест_юнита_преобразовать_yaml_в_объект_kotlin&quot;&gt;4.1. Тест юнита: Преобразовать YAML в объект Kotlin&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Мы начинаем с юнит-теста в`SiteBakerPluginTest.kt`чтобы проверить, что функция`parseSiteConfiguration`может правильно преобразовать строку YAML в объект`SiteConfiguration`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// plugin/src/test/kotlin/com/cheroliv/site/baker/SiteBakerPluginTest.kt
@Test
fun `can map configuration text to SiteConfiguration object`() {
    val yamlString = &quot;../../managed-jbake-context.yml&quot;
        .run(::File)
        .readText()
        .trimIndent()

    val config: SiteConfiguration = parseSiteConfiguration(yamlString)

    assertEquals(&quot;cheroliv.com&quot;, config.bake.cname)
    assertEquals(&quot;main&quot;, config.pushPage.branch)
    assertEquals(&quot;https://github.com/pages-content/pages-content.github.io.git&quot;, config.pushPage.repo.repository)
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Этот тест читает содержимое файла`managed-jbake-context.yml`(которое должно существовать для того, чтобы тест был корректен) и выполняет ассерции над объектом`SiteConfiguration`Полученное. Он подтверждает, что ключевые значения YAML правильно сопоставлены.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_4_2_тест_функциональный_проверить_чтение_файла_конфигурации&quot;&gt;4.2. Тест функциональный: Проверить чтение файла конфигурации&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Чтобы убедиться, что плагин может читать файл конфигурации через свой DSL и что парсинг работает в реальной среде Gradle, мы добавляем функциональный тест в`SiteBakerPluginFunctionalTest.kt`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Этот тест важен, поскольку он имитирует выполнение плагина в реальном проекте. Он должен быть&lt;strong&gt;герметичный&lt;/strong&gt;, то есть он должен сам создать файл`managed-jbake-context.yml`с контролируемым содержимым, для обеспечения воспроизводимости и изоляции теста&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// plugin/src/functionalTest/kotlin/com/cheroliv/site/baker/SiteBakerPluginFunctionalTest.kt
@Test
fun `config file contains good data`(){
    val configContent = configFile.readText(UTF_8)
    // Vérifications comme dans vos commentaires
    assertTrue(configContent.contains(&quot;bake&quot;))
    assertTrue(configContent.contains(&quot;pushPage&quot;))
    assertTrue(configContent.contains(&quot;repository&quot;))
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Этот функциональный тест проверяет, что скопированный файл конфигурации во временной директории теста содержит ожидаемые данные. Хотя этот тест не парсит YAML напрямую в объект Kotlin, он проверяет наличие файла и его содержимого, что является необходимым предварительным шагом перед парсингом плагином.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_5_визуализация_потока_парсинга&quot;&gt;5. Визуализация потока парсинга&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Следующая диаграмма иллюстрирует поток данных и взаимодействия при разборе конфигурации YAML:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
actor &quot;Пользователь Gradle&quot; as User
participant &quot;build.gradle.kts&quot; as BuildScript
participant &quot;SiteBakerPlugin&quot; as Plugin
participant &quot;Расширение сайта&quot; as Extension
participant &quot;managed-jbake-context.yml&quot; as ConfigFile
participant &quot;parseSiteConfiguration()&quot; as Parser
participant &quot;SiteConfiguration (объект Kotlin)&quot; as KotlinObject

User -&amp;gt; BuildScript : Applique le plugin et configure le DSL
BuildScript -&amp;gt; Plugin : apply()
Plugin -&amp;gt; Extension : Crée et enregistre l&#39;extension &#39;site&#39;
User -&amp;gt; BuildScript : site { configPath = &quot;...&quot; }
BuildScript -&amp;gt; Extension : Définit configPath

Plugin -&amp;gt; ConfigFile : Lit le fichier (via configPath)
ConfigFile --&amp;gt; Plugin : Contenu YAML
Plugin -&amp;gt; Parser : Appelle parseSiteConfiguration(yamlString)
Parser -&amp;gt; KotlinObject : Mappe le YAML en objet SiteConfiguration
KotlinObject --&amp;gt; Plugin : Retourne l&#39;objet configuré

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_заключение&quot;&gt;Заключение&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Следуя подходу TDD, мы успешно интегрировали библиотеку Jackson для парсинга файлов конфигурации YAML в объекты Kotlin внутри нашего Gradle‑плагина. Этот метод позволил нам:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Четко моделировать&lt;/strong&gt;наша конфигурация с data classes Kotlin.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Подтвердить логику парсинга&lt;/strong&gt;с целевыми юнит-тестами.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Обеспечить интеграцию&lt;/strong&gt;в реальной среде Gradle благодаря герметичными функциональными тестами&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Эта надежная основа дает нам большую уверенность в расширении нашего плагина функционалом, основанным на этой конфигурации, обеспечивая при этом поддерживаемость и надежность кода. Парсинг YAML теперь является надежной и протестированной функцией нашего плагина.&lt;code&gt;site-baker&lt;/code&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Table of Contents&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_инициализация_проекта&quot;&gt;Инициализация проекта&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_2_наш_первый_цикл_tdd_записать_задачу&quot;&gt;2. Наш первый цикл TDD: Записать задачу&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_2_1_тест_сначала_тест_который_не_проходит&quot;&gt;2.1. Тест сначала (Тест, который не проходит)&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_2_2_затем_код_пройти_тест&quot;&gt;2.2. Затем код (пройти тест)&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_3_второй_цикл_tdd_добавить_расширение_dsl&quot;&gt;3. Второй цикл TDD: добавить расширение DSL&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_3_1_тест_сначала&quot;&gt;3.1. Тест сначала&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_3_2_затем_код&quot;&gt;3.2. Затем код&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_4_функциональное_тестирование_проверить_интеграцию&quot;&gt;4. Функциональное тестирование: Проверить интеграцию&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_4_1_тест_интеграции_создать_контролируемую_среду&quot;&gt;4.1. Тест интеграции : создать контролируемую среду&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_4_2_завершить_логику&quot;&gt;4.2. Завершить логику&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_вывод&quot;&gt;Вывод&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div id=&quot;preamble&quot;&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;В этой статье мы рассмотрим, как создать надёжную основу разработки для плагина Gradle, используя подход разработки, управляемой тестами (TDD — Test-Driven Development). Этот метод гарантирует, что наш код надёжен, поддерживаемый и точно соответствует требованиям с самого начала.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_инициализация_проекта&quot;&gt;Инициализация проекта&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Gradle значительно упрощает создание нового плагина с помощью команды`gradle init`. Выбирая создать &quot;Gradle Plugin&quot; на Kotlin, мы получаем готовую структуру проекта, включающую два важных типа тестов:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Юнит-тесты:&lt;/strong&gt;Расположены в`src/test`, они позволяют проверять изолированные компоненты нашего плагина, например, внутреннюю логику задачи или конфигурацию расширения. Они работают быстро и не требуют полного выполнения Gradle.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Функциональные тесты :&lt;/strong&gt;Расположены в`src/functionalTest`, они используют`GradleRunner`Для выполнения полной сборки Gradle во временном тестовом проекте. Это позволяет нам проверять реальное поведение плагина в контролируемой среде.&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_2_наш_первый_цикл_tdd_записать_задачу&quot;&gt;2. Наш первый цикл TDD: Записать задачу&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Наше первое требование простое: плагин должен зарегистрировать задачу с именем`printSiteConfig`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_2_1_тест_сначала_тест_который_не_проходит&quot;&gt;2.1. Тест сначала (Тест, который не проходит)&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Согласно TDD, сначала мы пишем тест, который проверяет наличие этой задачи. В`SiteBakerPluginTest.kt`(наш файл юнит-теста), мы добавляем:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;@Test
fun `plugin registers task`() {
    // Créer un projet de test en mémoire
    val project = ProjectBuilder.builder().build()
    project.plugins.apply(&quot;com.cheroliv.site-baker&quot;)

    // Vérifier que la tâche a bien été enregistrée
    assertNotNull(project.tasks.findByName(&quot;printSiteConfig&quot;))
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Этот тест завершается с ошибкой, потому что мы ещё не написали ни единой строки кода в нашем плагине.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_2_2_затем_код_пройти_тест&quot;&gt;2.2. Затем код (пройти тест)&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Теперь мы пишем минимально необходимый код в`SiteBakerPlugin.kt`чтобы тест прошёл :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;class SiteBakerPlugin: Plugin&amp;lt;Project&amp;gt; {
    override fun apply(project: Project) {
        // Enregistrer une tâche simple
        project.tasks.register(&quot;printSiteConfig&quot;) { task -&amp;gt;
            // ... la logique de la tâche viendra plus tard
        }
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Мы перезапускаем тесты, и они проходят. Наша первая функция подтверждена.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_3_второй_цикл_tdd_добавить_расширение_dsl&quot;&gt;3. Второй цикл TDD: добавить расширение DSL&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Следующее требование — позволить пользователям настраивать наш плагин с помощью блока DSL в их`build.gradle.kts`. Мы хотим блок`site { &amp;#8230;&amp;#8203; }`где можно указать путь к конфигурации.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_3_1_тест_сначала&quot;&gt;3.1. Тест сначала&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Мы добавляем тест для проверки, что расширение`site`хорошо зарегистрирована и можно присвоить ей значение.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;@Test
fun `plugin registers extension`() {
    val project = ProjectBuilder.builder().build()
    project.plugins.apply(&quot;com.cheroliv.site-baker&quot;)

    // Récupérer l&#39;extension et lui affecter une valeur
    project.extensions
        .findByType(SiteExtension::class.java)!!
        .configPath
        .set(&quot;config.yml&quot;)

    // Vérifier que la valeur a bien été prise en compte
    assertEquals(
        &quot;config.yml&quot;,
        project.extensions.findByType(SiteExtension::class.java)?.configPath?.get()
    )
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Этот тест не проходит потому что ни класс`SiteExtension`ни регистрация расширения не существует.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_3_2_затем_код&quot;&gt;3.2. Затем код&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Мы создаём класс`SiteBakerExtension.kt`и обновляем`SiteBakerPlugin.kt` :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// SiteBakerExtension.kt
open class SiteExtension @Inject constructor(objects: ObjectFactory) {
    val configPath: Property&amp;lt;String&amp;gt; = objects.property(String::class.java)
}

// SiteBakerPlugin.kt
class SiteBakerPlugin: Plugin&amp;lt;Project&amp;gt; {
    override fun apply(project: Project) {
        // Enregistrer l&#39;extension
        val extension = project.extensions.create(&quot;site&quot;, SiteExtension::class.java)

        project.tasks.register(&quot;printSiteConfig&quot;) { task -&amp;gt;
            task.doLast {
                // On utilisera l&#39;extension plus tard
            }
        }
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Тесты снова проходят.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_4_функциональное_тестирование_проверить_интеграцию&quot;&gt;4. Функциональное тестирование: Проверить интеграцию&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Теперь, когда модули протестированы, нам нужно убедиться, что всё работает вместе в реальной сборке. Это роль функционального теста в`SiteBakerPluginFunctionalTest.kt`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_4_1_тест_интеграции_создать_контролируемую_среду&quot;&gt;4.1. Тест интеграции : создать контролируемую среду&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Этот тест будет моделировать настоящий проект, использующий наш плагин. Чтобы он был надежным, он должен быть&lt;strong&gt;герметичный&lt;/strong&gt;, то есть он не должен зависеть от существующих файлов в системе. Он должен сам создать все необходимые условия для своего выполнения.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Таким образом, тест:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;Создать`build.gradle.kts`теста, который использует наш плагин и его DSL.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Создать файл конфигурации&lt;/strong&gt;(&lt;code&gt;managed-jbake-context.yml&lt;/code&gt;) что плагин должен читать. Это важный этап для надежности теста.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Выполнить задачу`printSiteConfig`через`GradleRunner`.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Проверьте, что вывод сборки корректен.&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Копируя или создавая этот файл конфигурации при каждом запуске, мы гарантируем, что тест&lt;strong&gt;воспроизводимый&lt;/strong&gt;et не зависит от внешнего состояния. Это защищает наши тесты от регрессий, которые могут быть связаны с чтением файла.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;@Test fun `can run task with DSL`() {
    // 1. Créer un build.gradle.kts de test
    buildFile.writeText(&quot;&quot;&quot;
        plugins { id(&quot;com.cheroliv.site-baker&quot;) }
        site { configPath = &quot;managed-jbake-context.yml&quot; }
    &quot;&quot;&quot;.trimIndent())

    // 2. Créer le fichier de configuration pour un test contrôlé
    val configFile = File(projectDir, &quot;managed-jbake-context.yml&quot;)
    configFile.writeText(&quot;site: { title: &#39;Mon Site de Test&#39; }&quot;) // Contenu YAML simple

    // 3. Exécuter la build
    val runner = GradleRunner.create()
    runner.withPluginClasspath()
    runner.withArguments(&quot;printSiteConfig&quot;)
    runner.withProjectDir(projectDir) // Spécifier le répertoire du projet de test
    val result = runner.build()

    // 4. Vérifier la sortie
    assertTrue(result.output.contains(&quot;Site config path: managed-jbake-context.yml&quot;))
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Этот тест будет неудачным до тех пор, пока задача`printSiteConfig`Оно не будет фактически использовать значение расширения.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_4_2_завершить_логику&quot;&gt;4.2. Завершить логику&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Мы обновляем задачу в`SiteBakerPlugin.kt`чтобы она отображала настроенное значение :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;project.tasks.register(&quot;printSiteConfig&quot;) { task -&amp;gt;
    task.doLast {
        println(&quot;Site config path: ${extension.configPath.get()}&quot;)
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Все тесты, как unit, так и functional, теперь проходят.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_вывод&quot;&gt;Вывод&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Следуя подходу TDD, мы построили плагин инкрементально и безопасно. Каждая небольшая функция сразу проверяется тестом, от быстрых юнит-тестов до функциональных тестов, подтверждающих полную интеграцию.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Старавшись сделать наши тесты функциональными&lt;strong&gt;герметичные&lt;/strong&gt;— особенно программно создавая необходимые файлы конфигурации — мы строим чрезвычайно надежный защитный механизм. Эта строгость эффективно защищает нас от регрессий и дает нам большую уверенность для добавления более сложных функций позже, таких как анализ YAML-файла конфигурации.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Эта прочная база тестов является самым ценным активом для обслуживания и будущего развития плагина.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Sommaire&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_введение&quot;&gt;Введение&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_шаг_1_запустить_ассистент_проекта&quot;&gt;Шаг 1: Запустить ассистент проекта&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_шаг_2_понять_сгенерированную_структуру&quot;&gt;Шаг 2 : Понять сгенерированную структуру&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_ключевые_файлы_и_папки&quot;&gt;Ключевые файлы и папки&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_введение&quot;&gt;Введение&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;Целевая аудитория: начинающий и средний разработчик с Gradle.&lt;/div&gt;
&lt;p&gt;Запуск нового проекта плагина Gradle может показаться пугающим. К счастью, Gradle предоставляет мощный интерактивный помощник, задача`init`, который генерирует полную, чистую и готовую к использованию структуру проекта. Это руководство покажет вам, как использовать этот инструмент для создания здоровой основы плагина, объяснит структуру и покажет, как запустить первые задачи сборки.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_шаг_1_запустить_ассистент_проекта&quot;&gt;Шаг 1: Запустить ассистент проекта&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Команда`gradle init`является исходной точкой. Она запускает помощник в командной строке, который задаёт вам серию вопросов для настройки проекта.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Откройте терминал в пустой папке и выполните:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;gradle init&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ассистент проведёт вас. Вот варианты, которые нужно выбрать для плагина Gradle, написанного на Kotlin :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Выберите тип проекта для генерации:&lt;/strong&gt;Выберите`Gradle plugin`.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Выберите язык реализации:&lt;/strong&gt;Выберите`Kotlin`.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Выберите DSL скрипта сборки:&lt;/strong&gt;Выберите`Kotlin`.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Название проекта:&lt;/strong&gt;Введите имя для вашего проекта (например:`site-baker`).&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;ID плагина:&lt;/strong&gt;Дайте вашему плагину уникальный идентификатор (например:`com.cheroliv.site-baker`).&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Класс плагина:&lt;/strong&gt;Укажите имя класса реализации (например:`com.cheroliv.SiteBakerPlugin`).&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;После завершения Gradle генерирует полное дерево файлов.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;title&quot;&gt;Диаграмма процесса инициализации&lt;/div&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
start
:Lancer `gradle init`;
:Choisir &quot;плагин Gradle&quot;;
:Choisir &quot;Kotlin&quot; (langage);
:Choisir &quot;Kotlin&quot; (DSL);
:Saisir nom, ID, et classe;
:Projet généré;
stop
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_шаг_2_понять_сгенерированную_структуру&quot;&gt;Шаг 2 : Понять сгенерированную структуру&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ассистент создает модульную структуру проекта, разделяя корневой проект и исходный код самого плагина.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-text hljs&quot; data-lang=&quot;text&quot;&gt;.
├── gradle/
│   └── wrapper/
│       ├── gradle-wrapper.jar
│       └── gradle-wrapper.properties
├── gradlew
├── gradlew.bat
├── plugin/
│   ├── build.gradle.kts
│   └── src/
│       ├── main/
│       │   └── kotlin/
│       │       └── com/cheroliv/SiteBakerPlugin.kt
│       ├── test/
│       │   └── kotlin/
│       │       └── com/cheroliv/SiteBakerPluginTest.kt
│       └── functionalTest/
│           └── kotlin/
│               └── com/cheroliv/SiteBakerPluginFunctionalTest.kt
└── settings.gradle.kts&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ключевые_файлы_и_папки&quot;&gt;Ключевые файлы и папки&lt;/h3&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;settings.gradle.kts&lt;/code&gt; : Этот файл в корне определяет модули, включённые в сборку. Здесь он включает подпроект`plugin`.&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;[source,kotlin] ---- rootProject.name = &quot;site-baker include(&quot;plugin&quot;) ----&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Sommaire&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_введение&quot;&gt;Введение&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_1_jdk_движок_gradle&quot;&gt;1. JDK: движок Gradle&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_какую_версию_выбрать&quot;&gt;Какую версию выбрать?&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_установка_через_sdkman_рекомендуется&quot;&gt;Установка через SDKMAN! (рекомендуется)&lt;/a&gt;
&lt;ul class=&quot;sectlevel3&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_установить_sdkman&quot;&gt;&lt;strong&gt;Установить SDKMAN!&lt;/strong&gt;&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_установить_версию_jdk&quot;&gt;Установить версию JDK&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_проверить_установку&quot;&gt;Проверить установку&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_2_ide_intellij_idea&quot;&gt;2. IDE: IntelliJ IDEA&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_3_gradle_инструмент_сборки&quot;&gt;3. Gradle: Инструмент сборки&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_установка_через_sdkman&quot;&gt;Установка через SDKMAN!&lt;/a&gt;
&lt;ul class=&quot;sectlevel3&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_установить_gradle&quot;&gt;&lt;strong&gt;Установить Gradle&lt;/strong&gt;&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_проверить_установку_2&quot;&gt;Проверить установку&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_4_jbake_генератор_статических_сайтов&quot;&gt;4. JBake : Генератор статических сайтов&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_установка_через_sdkman_2&quot;&gt;Установка через SDKMAN!&lt;/a&gt;
&lt;ul class=&quot;sectlevel3&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_установить_jbake&quot;&gt;Установить JBake&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_проверить_установку_3&quot;&gt;Проверить установку&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_5_обёртка_gradle_абсолютная_лучшая_практика&quot;&gt;5. Обёртка Gradle: абсолютная лучшая практика&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_6_docker_и_portainer_для_воспроизводимых_сборок_опционально&quot;&gt;6. Docker и Portainer: для воспроизводимых сборок (опционально)&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_установка_docker_engine&quot;&gt;Установка Docker Engine&lt;/a&gt;
&lt;ul class=&quot;sectlevel3&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_установить_docker_через_официальный_скрипт&quot;&gt;&lt;strong&gt;Установить Docker через официальный скрипт :&lt;/strong&gt;&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_управлять_docker_без_sudo_рекомендовано&quot;&gt;&lt;strong&gt;Управлять Docker без &lt;code&gt;sudo&lt;/code&gt; (рекомендовано):&lt;/strong&gt;&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
