&lt;div id=&quot;preamble&quot;&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;github repository: &lt;a href=&quot;https://github.com/cheroliv/js-codebase&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;js-codebase&lt;/a&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
