&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_map_reduce&quot;&gt;map reduce&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Преобразовать один список бит в один список строк и резюмировать список строк&lt;br&gt;
в строке, содержащей конкатенацию. Как залогировать запрос, отправленный (requestBodyContent:byte[])&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;log.info(
    requestBodyContent!!.map { it.toInt().toChar().toString() }
        .reduce { request: String, s: String -&amp;gt; request + s }
)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_enum_и_sealed_классы&quot;&gt;enum и sealed-классы&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;пост:&lt;a href=&quot;0038_training_kotlin_enum_sealed_class_post&quot; target=&quot;&quot;_blank&quot;&gt;обучение kotlin enum запечатанный класс&lt;/a&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_функциональный_интерфейс_и_ссылка_на_метод&quot;&gt;функциональный интерфейс и ссылка на метод&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Можно преобразовать сущность в модель домена DTO с помощью метода-ссылки (функциональный стиль- java 8)&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;fun findAllByLoginNot(
        pageable:Pageable,
        login:String)
    :Page&amp;lt;UserDto&amp;gt; {
    return userDao.findAllByLoginNot(
                    pageable,
                    login).map(::fromEntity)
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;однаhttps://stackoverflow.com/a/22245383/837404[хорошее объяснение]&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_захватить_стандартный_вывод&quot;&gt;Захватить стандартный вывод&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;package functional

import java.io.ByteArrayOutputStream
import java.io.PrintStream
import java.lang.System.out
import java.lang.System.setOut
import kotlin.test.AfterTest
import kotlin.test.BeforeTest
import kotlin.test.Test
import kotlin.test.assertEquals


class BasicsHOF {
    private val standardOut: PrintStream? = out
    private val outputStreamCaptor = ByteArrayOutputStream()

    @BeforeTest
    fun setUp() = setOut(PrintStream(outputStreamCaptor))

    @AfterTest
    fun tearDown() = setOut(standardOut)

    @Test
    fun `three times dope`() {

        3.times { println(&quot;Hello&quot;) }

        assertEquals(
            buildString {
                repeat(3) { append(&quot;Hello\n&quot;) }
                deleteAt(length - 1)
            }, outputStreamCaptor
                .toString()
                .trim()
        )
    }

    fun Int.times(fn: () -&amp;gt; Unit) = (1..this).forEach { _ -&amp;gt; fn() }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_чем_в_kotlin_отличаются_apply_run_let_also_use_и_with&quot;&gt;Чем в Kotlin отличаются apply, run, let, also, use и with ?&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Сравнение функций Kotlin и использование форм лямбда Reference&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_применить&quot;&gt;применить&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;Введение Функции Kotlin`apply`, &lt;code&gt;run&lt;/code&gt;, &lt;code&gt;let&lt;/code&gt;, &lt;code&gt;also&lt;/code&gt;, &lt;code&gt;use&lt;/code&gt;, et `with`Предлагают разные способы обработки объектов. Каждая имеет свои варианты использования и поведение. Кроме того, формы ссылок на лямбда позволяют сделать код более читаемым и повторно используемым, ссылаясь на существующие лямбда-функции.&lt;/div&gt;
&lt;p&gt;Функция`apply`используется для настройки объекта во время его создания. Она возвращает объект, на котором она вызывается.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Пример со ссылкой на lambda :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;val someObject = SomeClass().apply(::configureObject)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Пример с lambda :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;val someObject = SomeClass().apply {
// configuration des propriétés de someObject
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_run&quot;&gt;run&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Функция`run`используется для выполнения блока кода над объектом и возвращает результат блока кода.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Пример с lambda reference :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;val result = someObject.run(::someFunction)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Пример с lambda :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;val result = someObject.run {
// bloc de code à exécuter sur someObject
// la dernière expression est renvoyée
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_laissez&quot;&gt;laissez&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Функция`let`используется для выполнения блока кода над объектом и возвращает результат блока кода.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Пример со ссылкой на lambda&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;val result = someObject.let(::processObject)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Пример с lambda :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;val result = someObject.let {
// bloc de code à exécuter sur someObject
// la dernière expression est renvoyée
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_также&quot;&gt;также&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Функция`also`используется для выполнения дополнительного действия с объектом и возвращает объект, на котором она вызывается.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Пример с lambda reference :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;someObject.also(::performAdditionalAction)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Пример с lambda :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;someObject.also {
// action additionnelle sur someObject
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_use&quot;&gt;use&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Функция`use`используется для работы с ресурсами, которые должны быть закрыты после использования. Она автоматически вызывает функцию`close`в конце блока.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Пример с лямбда-ссылкой :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;someResource.use(::useResource)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Пример с lambda :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;someResource.use {
// travailler avec la ressource
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_с&quot;&gt;с&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Функция`with`используется для вызова нескольких методов у объекта без повторения его имени и возвращает результат последнего выражения.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Пример с lambda reference :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;val result = with(someObject, ::processWithObject)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Пример с lambda :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;val result = with(someObject) {
// appeler des méthodes sur someObject
// la dernière expression est renvoyée
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Используя формы lambda reference или блоки`{}`, вы можете инкапсулировать логику в отдельные функции, тем самым улучшая читаемость и переиспользуемость кода.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_let_function_в_kotlin&quot;&gt;let Function в Kotlin&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;Ли let возвращает объект с применёнными к нему побочными эффектами или в начальном состоянии входа в зависимости от (let) ?&lt;/div&gt;
&lt;p&gt;Функция`let`В Kotlin используется для выполнения операций над объектом и возврата другого результата. Однако важно отметить, что функция`let`не изменяет начальное состояние объекта, на котором она вызывается&lt;/p&gt;
&lt;/div&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;colgroup&gt;
&lt;col style=&quot;width: 50%;&quot;&gt;
&lt;col style=&quot;width: 50%;&quot;&gt;
&lt;/colgroup&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;strong&gt;Подпись&lt;/strong&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;inline fun &amp;lt;T, R&amp;gt; T.let(block: (T) &amp;#8594; R): R&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;colgroup&gt;
&lt;col style=&quot;width: 50%;&quot;&gt;
&lt;col style=&quot;width: 50%;&quot;&gt;
&lt;/colgroup&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;strong&gt;использование&lt;/strong&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Функция`let`Обычно используется для применения преобразований к объекту и получения результата, основанного на этих преобразованиях.&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;colgroup&gt;
&lt;col style=&quot;width: 50%;&quot;&gt;
&lt;col style=&quot;width: 50%;&quot;&gt;
&lt;/colgroup&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;strong&gt;Результат&lt;/strong&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Значение, возвращаемое функцией`let`является результатом лямбда-выражения, переданного в качестве аргумента, обычно результатом операций, выполненных над объектом.&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;colgroup&gt;
&lt;col style=&quot;width: 50%;&quot;&gt;
&lt;col style=&quot;width: 50%;&quot;&gt;
&lt;/colgroup&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;strong&gt;Пограничные эффекты&lt;/strong&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Хотя функция`let`может иметь побочные эффекты на объекте, когда она используется в лямбда-выражении, она не изменяет исходное состояние самого объекта&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Таким образом, функция`let`является элегантным способом выполнять операции над объектом, одновременно получая производный результат, сохраняя при этом целостность исходного объекта.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;toc&quot;&gt;table des matières&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;#char&quot;&gt;chaines de caractères et caractères&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;#math&quot;&gt;nombres et math&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;#date&quot;&gt;dates et heures&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;#java8date&quot;&gt;dates et heures java8&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;#arrCol&quot;&gt;tableaux et collections&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;#sysProp&quot;&gt;System.Properties&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;#threads&quot;&gt;Threads&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;#regex&quot;&gt;Expressions Régulières&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;char&quot;&gt;chaines de caractères et caractères&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;import java.text.Collator
import java.util.*
import kotlin.test.*

class StringsTest {
    @Test
    fun `chaines de caractères et caractères`() {
        //inférence de type
        val s = &quot;C&#39;est&quot;
        assertEquals(&quot;C&#39;est&quot;, s)

        //concaténation
        val t: String = s + &quot; le moment.&quot;
        assertEquals(&quot;C&#39;est le moment.&quot;, t)

        // StringBuilder
        val t1: String = s + buildString { append(&quot; le moment.&quot;) }
        assertEquals(&quot;C&#39;est le moment.&quot;, t1)

        //interpolation
        val t2 = &quot;$s le moment.&quot;
        assertEquals(&quot;C&#39;est le moment.&quot;, t2)

        //multiligne chaine de caractères
        val t3 = &quot;&quot;&quot;$s le moment.&quot;&quot;&quot;
        assertEquals(&quot;C&#39;est le moment.&quot;, t3)

        //conversion de type
        val t4 = t + &quot; &quot; + 23.4
        assertEquals(&quot;C&#39;est le moment. 23.4&quot;, t4)

        val t5 = &#39;C&#39;.toString()
        assertEquals(&quot;C&quot;, t5)

        //taille de la chaine de caractères
        assertEquals(16, t.length)

        //sous-chaine d&#39;une chaine de caractères

        //retourne une chaine de caractères contenant,
        //les caractères aux positions x à y-1
        //sub = t.substring(x, y)

        //t = &quot;C&#39;est le moment.&quot;
        //retourne les caractères 6 et 7
        var sub = t.substring(6, 8)
        assertEquals(&quot;le&quot;, sub)

        //retourne les caractères 0 à 4
        sub = t.substring(0, 5)
        assertEquals(&quot;C&#39;est&quot;, sub)

        //la longueur d&#39;une sous-chaine est toujours égale (y-x)
        val numChars = sub.length
        assertEquals(5 - 0, numChars)

        //extraction des caractères d&#39;une chaine
        assertEquals(&#39;e&#39;, t.elementAt(2))
        assertEquals(&#39;e&#39;, t.get(2))
        assertEquals(&#39;e&#39;, t[2])

        //conversion d&#39;une chaine en tableau de caractères
        val ca = t.toCharArray()
        assertEquals(t.length, ca.size)
        t.mapIndexed { index, char -&amp;gt; assertEquals(char, ca[index]) }

        //place les 4 premiers caractères de t1
        //dans le tableau ca a la position 2
        (t as java.lang.String).getChars(
            /* srcBegin = */ 0,
            /* srcEnd = */ 3,
            /* dst = */ ca,
            /* dstBegin = */ 1
        )
        assertEquals(&quot;CC&#39;et le moment.&quot;, String(ca))
        //colle tous les caractères dans un meme string
        assertEquals(&quot;CC&#39;et le moment.&quot;, ca.concatToString())

        //to lower case
        assertEquals(&quot;c&#39;est le moment.&quot;, t.toLowerCase())
        assertEquals(&quot;c&#39;est le moment.&quot;, t.lowercase())

        //to upper case
        assertEquals(&quot;C&#39;EST LE MOMENT.&quot;, t.toUpperCase())
        assertEquals(&quot;C&#39;EST LE MOMENT.&quot;, t.uppercase())

        //comparaison de chaines de caractères
        //t = &quot;C&#39;est le moment.&quot;
        assertFalse(t.equals(&quot;hello&quot;))
        assertFalse(t == &quot;hello&quot;)

        //ignore la casse
        assertTrue(t.equalsIgnoreCase(&quot;C&#39;EST LE MOMENT.&quot;))
        assertTrue(t.equals(&quot;C&#39;EST LE MOMENT.&quot;, ignoreCase = true))

        //démarre par
        assertTrue(t.startsWith(&quot;C&#39;est&quot;))
        //se finit par
        assertTrue(t.endsWith(&quot;le moment.&quot;))

        //compareTo
        //retourne une valeur &amp;lt; 0, car s est
        //alphabétiquement avant &quot;N&#39;est&quot;
        val r1: Int = s.compareTo(&quot;N&#39;est&quot;)
        assertTrue(r1 &amp;lt; 0)

        //variante ignorant la casse
        val r1Prime: Int = (s as java.lang.String).compareToIgnoreCase(&quot;n&#39;est&quot;)
        assertTrue(r1Prime &amp;lt; 0)

        //retourne 0 si les chaines sont equivalente
        val r2: Int = s.compareTo(&quot;C&#39;est&quot;)
        assertEquals(0, r2)

        //retourne une valeur &amp;gt; 0 car s vient apres &quot;B&#39;est&quot;
        val r3: Int = s.compareTo(&quot;B&#39;est&quot;)
        assertTrue(r3 &amp;gt; 0)

        //Recherche de caractères et de sous-chaines de caractères

        //recherche de caractères
        //position du premier caractères &#39;t&#39;
        var pos = t.indexOf(&#39;t&#39;)
        assertEquals(4, pos)

        //position du suivant
        pos = t.indexOf(&#39;t&#39;, pos + 1)
        assertEquals(14, pos)

        //retour d&#39;érreur -1 si absence de suivant
        pos = t.indexOf(&#39;t&#39;, pos + 1)
        assertEquals(-1, pos)

        //position du dernier &#39;t&#39; dans la chaine: 14
        pos = t.lastIndexOf(&#39;t&#39;)
        assertEquals(14, pos)

        //recherche de &#39;t&#39; vers l&#39;arrière a partir du caractères 13
        pos = t.lastIndexOf(&#39;t&#39;, pos - 1)
        assertEquals(4, pos)

        //recherche de sous-chaines
        //retourne 2
        pos = t.indexOf(&quot;est&quot;)
        assertEquals(2, pos)

        //&quot;est&quot; n&#39;apparait qu&#39;une seule fois: retourne -1
        pos = t.indexOf(&quot;est&quot;, pos + 1)
        assertEquals(-1, pos)

        //recherche d&#39;une sous-chaine depuis l&#39;arrière
        //t = &quot;C&#39;est le moment.&quot;
        //retourne 6
        pos = t.lastIndexOf(&quot;le &quot;)
        assertEquals(6, pos)

        //extrait depuis la position 9,
        //renvoi toute la chaine après &quot;le &quot;
        val noun = t.substring(pos + 3)
        assertEquals(-1, noun.indexOf(&quot;le &quot;))

        //remplacement de toutes les instances d&#39;un caractère
        //par un autre caractère
        //ne fonctionne que avec les caractères, pas les chaines
        val exclaim: String = t.replace(&#39;.&#39;, &#39;!&#39;)
        assertEquals(&#39;!&#39;, exclaim.get(exclaim.length - 1))
        assertEquals(exclaim.length - 1, exclaim.indexOf(&#39;!&#39;))
        assertEquals(-1, exclaim.indexOf(&#39;.&#39;))

        //suppression des espaces blancs
        //au début et à la fin d&#39;une chaine
        val noextraspaces = t.trim()
        assertNotEquals(&#39; &#39;, noextraspaces.get(0))
        assertNotEquals(&#39; &#39;, noextraspaces.get(noextraspaces.length - 1))

        //extraction des instances uniques de chaines de caractères
        //avec intern()
        val s1 = s.intern()
        assertEquals(s, s1)
        val s2 = &quot;C&#39;est&quot;.intern()
        assertEquals(&quot;C&#39;est&quot;, s2)
        assertEquals(s1, s2)

        //StringBuilder pour manipuler les caractères d&#39;une chaine de caractères
        //crée un tampon StringBuilder à partir d&#39;une chaine de caractères
        val b = StringBuilder(&quot;N&#39;est&quot;)

        //extrait et définit des caractères individuel du tampon StringBuilder
        //le caractères à l&#39;index 0
        val c: Char = b.get(0)
        assertEquals(&#39;N&#39;, c)

        //modifier le premier caractère de la chaine
        b.setCharAt(0, &#39;C&#39;)
        assertEquals(s, b.toString())

        //ajouter des données à un StringBuilder
        b.append(&#39; &#39;)
        b.append(&quot;le moment.&quot;)
        b.append(23)

        //insère des chaines de caractères ou autre dans le StringBuilder
        b.insert(6, &quot;pas &quot;)
        assertEquals(&quot;C&#39;est pas le moment.23&quot;, b.toString())

        //remplace un sous ensemble de caractères
        //avec une chaine de caractères donnée
        b.replace(2, 9, &quot;est&quot;)
        assertEquals(&quot;C&#39;est le moment.23&quot;, b.toString())

        //supprime les caractères
        b.delete(15, 18)
        assertEquals(&quot;C&#39;est le moment&quot;, b.toString())
        b.deleteCharAt(2)
        assertEquals(&quot;C&#39;st le moment&quot;, b.toString())

        //insert à la postion 2 et décale reste à droite(sans perte de données)
        b.insert(2, &#39;e&#39;)

        //tronque la taille de la donnée
        b.setLength(5)
        assertEquals(&quot;C&#39;est&quot;, b.toString())

        //inverse les caractères de la chaine
        b.reverse()
        assertEquals(&quot;tse&#39;C&quot;, b.toString())

        //écrase le StringBuilder, pret à etre réutilisé
        b.setLength(0)
        assertEquals(&quot;&quot;, b.toString())

        //java.util.StringTokenizer pour fragmenter une chaine
        //de caractères en un ensemble de mots
        var st = StringTokenizer(t)
        //nb d&#39;items encore présentent dans la file
        assertEquals(3, st.countTokens())

        //est ce que il y a encore des items dans la file
        assertTrue(st.hasMoreTokens())

        //récupérer le token courrant
        assertEquals(&quot;C&#39;est&quot;, st.nextToken())
        assertEquals(&quot;le&quot;, st.nextToken())
        assertEquals(&quot;moment.&quot;, st.nextToken())
        assertFalse(st.hasMoreTokens())
        assertEquals(0, st.countTokens())

        //extraire des occurences de mots délimités
        //par des caractères autres que des expaces.
        val str = &quot;a:b:c:d&quot;
        st = StringTokenizer(str, &quot;:&quot;)
        assertEquals(4, st.countTokens())
        assertTrue(st.hasMoreTokens())
        assertEquals(&quot;a&quot;, st.nextToken())
        assertEquals(&quot;b&quot;, st.nextToken())
        assertEquals(&quot;c&quot;, st.nextToken())
        assertEquals(&quot;d&quot;, st.nextToken())
        assertFalse(st.hasMoreTokens())
        assertEquals(0, st.countTokens())


        //text=&quot;C&#39;est le moment.&quot;
        val text = t.toCharArray()
        var p = 0

        //sauter les espaces de tete
        //pour ramener p à la position du premier caractère imprimable
        while ((p &amp;lt; text.size) &amp;amp;&amp;amp;
            (Character.isWhitespace(text[p]))
        ) p++
        assertEquals(0, p)
        assertEquals(&quot;C&#39;est le moment.&quot;, text.concatToString())

        //met le premier mot du texte en majuscule
        while (p &amp;lt; text.size &amp;amp;&amp;amp; Character.isLetter(text[p])) {
            text[p] = Character.toUpperCase(text[p])
            p++
        }
        assertEquals(1, p)
        assertEquals(&#39;C&#39;, text[0])
        assertTrue(Character.isUpperCase(text[0]))
        assertFalse(Character.isLetter(text[1]))

        //comparer des chaines de caractères
        // avec les contrainte la locale système
        val col = Collator.getInstance()
        //le résulat est négatif car chica
        //est avant chico dans l&#39;ordre alphabétique
        assertTrue(col.compare(&quot;chica&quot;, &quot;chico&quot;) &amp;lt; 0)
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;a href=&quot;#toc&quot;&gt;table des matières&lt;/a&gt;&lt;/p&gt;
